insert into new_text values
  ($t$alpin-flohmi-bern$t$, 'de', $t$Flohmarkt für gebrauchte Bergsportausrüstung im Alpinen Museum Bern: Kletterausrüstung, Skimaterial, Wanderkleidung und mehr – weitergegeben statt neu gekauft. Das Material wird vor Ort gratis geprüft. Einmal im Jahr, im Oktober. Eintritt frei; organisiert von Mountain Wilderness Schweiz.$t$),
  ($t$alpin-flohmi-bulle$t$, 'de', $t$Flohmarkt für gebrauchte Bergsportausrüstung in Bulle. Hier gibt es Kletterausrüstung, Skimaterial, Wanderkleidung und weitere Outdoor-Artikel aus zweiter Hand. Organisiert von Mountain Wilderness Schweiz. Eintritt frei.$t$),
  ($t$alpin-flohmi-interlaken$t$, 'de', $t$Der Alpin-Flohmi von Mountain Wilderness kommt nach Interlaken: ein Abendmarkt für gebrauchte Bergsportausrüstung im ORBIT in Wilderswil. Kletterausrüstung, Ski, Rucksäcke, Wanderkleidung und mehr wechseln von Privat zu Privat den Besitzer – nachhaltig statt neu. Wer verkaufen will, mietet einen Tisch; wer stöbern will, kommt einfach vorbei. Eintritt frei.$t$),
  ($t$alpin-flohmi-lausanne$t$, 'de', $t$Flohmarkt für gebrauchte Bergsportausrüstung in Lausanne. Kletterausrüstung, Skimaterial, Wanderkleidung und weitere Outdoor-Artikel lassen sich hier nachhaltig kaufen und verkaufen. Organisiert von Mountain Wilderness Schweiz. Eintritt frei.$t$),
  ($t$alpin-flohmi-luzern$t$, 'de', $t$Flohmarkt für gebrauchte Bergsportausrüstung in Luzern. Kletterausrüstung, Skimaterial, Wanderkleidung und weitere Outdoor-Artikel lassen sich hier nachhaltig kaufen und verkaufen. Organisiert von Mountain Wilderness Schweiz. Eintritt frei.$t$),
  ($t$alpin-flohmi-yverdon-les-bains$t$, 'de', $t$Flohmarkt für gebrauchte Bergsportausrüstung in Yverdon-les-Bains. Hier gibt es Kletterausrüstung, Skimaterial, Wanderkleidung und weitere Outdoor-Artikel aus zweiter Hand. Organisiert von Mountain Wilderness Schweiz. Eintritt frei.$t$),
  ($t$alpin-flohmi-zuerich$t$, 'de', $t$Flohmarkt für gebrauchte Bergsportausrüstung in der Region Zürich. Kletterausrüstung, Skimaterial, Wanderkleidung und weitere Outdoor-Artikel lassen sich hier nachhaltig kaufen und verkaufen. Organisiert von Mountain Wilderness Schweiz. Eintritt frei.$t$),
  ($t$altstadtflohmarkt-hannover$t$, 'de', $t$Deutschlands ältester Flohmarkt: seit April 1967 jeden Samstag von März bis Oktober am Leineufer in der Altstadt, gleich neben den Nanas. Antiquitäten, Schmuck, Schallplatten und Vintage, dazu ein Kinderflohmarkt und Crêpe-Stände. Private Verkäufer bauen ohne Anmeldung auf.$t$),
  ($t$antik-flohmarkt-fehraltorf$t$, 'de', $t$Der Antik-, Floh- und Sammlermarkt Fehraltorf findet zweimal im Jahr im und ums Heiget-Huus statt: rund 80 Ausstellende in der Halle, unter Dach und im Freien, alles ebenerdig. Antiquitäten, Sammlerstücke, Trödel; ein kleines Bistro mit Hausgemachtem und Grillwurst. Grosser Gratisparkplatz; vom Bahnhof Fehraltorf sind es zehn Minuten zu Fuss.$t$),
  ($t$antik-und-troedelmarkt-messe-halle-saale$t$, 'de', $t$Einmal im Monat samstags in den Messehallen, im Dezember auch sonntags; von Juni bis August ist Pause. Alte Möbel, Schmuck, Puppen, Porzellan, Glas, Silber, Uhren und Leinen, für Sammler dazu Münzen, alte Bücher und Briefmarken. Manche Händler schätzen Stücke kostenlos und kaufen von Privatleuten an. Eintritt 3 Euro, Kinder unter 12 frei.$t$),
  ($t$antikflohmarkt-trabrennbahn-karlshorst-berlin$t$, 'de', $t$Ein Antik- und Trödelmarkt auf dem weitläufigen Gelände der Trabrennbahn Karlshorst, mit Händlern aus ganz Deutschland und dem Ausland. Es gibt alte Möbel, Antiquitäten, Kunst und Design von Art déco bis Mid-Century, dazu viel schräges Secondhand. Auch grosse Stücke kommen gut nach Hause: Gegen eine kleine Gebühr parkst du direkt neben den Ständen.$t$),
  ($t$baden-bazaar$t$, 'de', $t$Ein Bazar an der Oberstadtstrasse 10A in Baden, mehr Lifestyle als klassischer Flohmarkt: Vintage-Kleidung, Handgemachtes, Deko und Food-Stände. Meist am zweiten Sonntag im Monat. Eintritt frei.$t$),
  ($t$bergflohmarkt-chur$t$, 'de', $t$Der Bergflohmarkt Chur ist ein spezialisierter Secondhand-Markt für Bergsport- und Outdoor-Ausrüstung und alpine Fundstücke, im Titthof direkt beim Bahnhof Chur. Der Verein Bergflohmarkt Chur führt ihn regelmässig durch und gibt die Termine auf seiner Website bekannt. Eintritt frei.$t$),
  ($t$bourse-jouets-collection-fribourg-granges-paccot$t$, 'de', $t$Eine Börse für altes Sammlerspielzeug mit 400 Tischen. Vor Ort gibt es ein Restaurant mit Kaffee und Sandwiches. Organisiert wird sie von Dakota Events, einem Familienbetrieb. Am selben Wochenende veranstaltet Dakota Events im Forum Fribourg auch eine Börse für Fotoapparate, alte Papiere, Bücher und Schallplatten.$t$),
  ($t$bourse-jouets-collection-geneve-le-grand-saconnex$t$, 'de', $t$Die 30. Ausgabe dieser Börse für Sammlerspielzeug im Palexpo. Sie findet gemeinsam mit der Vinyl- und CD-Börse statt; zusammen sind es über 200 Tische. Es gibt eine Bar mit kleinen Speisen.$t$),
  ($t$bourse-vinyls-cd-geneve-le-grand-saconnex$t$, 'de', $t$Die 5. Ausgabe dieser Börse für Schallplatten und CDs im Palexpo. Sie teilt sich den Tag mit der Börse für Sammlerspielzeug; zusammen sind es über 200 Tische.$t$),
  ($t$boutique-kleider-flohmarkt-wbz-reinach$t$, 'de', $t$Kleidung, Taschen und Schuhe – mehr gibt es hier nicht: Das ist der kleine Modeflohmarkt des WBZ. Das WBZ in Reinach setzt sich seit 1975 für Menschen mit Behinderung ein, und sein Flohmarkt-Team organisiert auch diesen Markt. Geschirr, Bilder und alles andere gibt es beim grossen viertägigen WBZ-Flohmarkt im selben Gebäude. Im Haus ist auch das WBZ-eigene Restaurant Piazza.$t$),
  ($t$breitsch-maerit-bern$t$, 'de', $t$Einmal im Jahr wird das Breitenrain-Quartier in Bern zum Garagen-Flohmarkt: Verkauft wird beim Hauseingang, im Garten und vor der Garage. Auch Quartierbetriebe machen mit; es gibt Essen und Trinken für Gross und Klein.$t$),
  ($t$brocante-17-terra-geneve$t$, 'de', $t$17 Terra ist ein Pop-up-Laden im Erdgeschoss in Eaux-Vives, der seine Fläche etwa jede Woche einer neuen Veranstaltung überlässt; diese Brocante ist eine davon. Professionelle Händlerinnen und Händler bringen Möbel, Spiegel, Bilder, Schmuck, Lampen, Geschirr und Dekoobjekte mit. Die Tram hält ein paar Schritte vor der Tür.$t$),
  ($t$brocante-de-carouge-geneve$t$, 'de', $t$Die Organisatoren wollen hier Antiquitäten und Brocante, keinen Ramschverkauf: nichts Neues, keine Restposten, keine Schilder mit «alles für 5 Franken». Die Ware liegt auf Tischen mit Tüchern, nie in Kartons am Boden. An Brocante-Tagen öffnen zudem rund zwanzig Geschäfte in ganz Carouge. Bei schlechtem Wetter kann der Markt ausfallen oder früher enden. Nach Carouge kommst du mit den Trams 12 und 18 und den Bussen 11 und 21; mit dem Auto gibt es die Parkhäuser Sardaigne und Octroi.$t$),
  ($t$brocante-de-chambrelien$t$, 'de', $t$Ein kleiner Trödelmarkt mit rund 20 Ständen, direkt an der Bahnlinie Neuchâtel–La Chaux-de-Fonds. Von 9 Uhr bis zum späten Nachmittag; im Bistro gibt es Gegrilltes, geröstete Maronen sowie Erbsen- und Kürbissuppe.$t$),
  ($t$brocante-de-la-gruyere-bulle$t$, 'de', $t$Espace Gruyère, das Ausstellungszentrum in Bulle, führt diese Messe in den eigenen Hallen durch. Die Händlerinnen und Händler bringen Möbel, Lampen, Sammlerstücke und Antiquitäten aus mehreren Jahrzehnten mit, und Watch&Write ist für alte Füllfedern und Uhren da. Am Samstag und Sonntag von 10.30 bis 13.30 Uhr schätzen zwei Fachleute Gegenstände kostenlos – das Stück vom Dachboden darf also mit. In der Halle gibt es ein Restaurant, einen Tea-Room, eine Bar und eine Pinte du terroir. Der Bus 202 hält vor dem Eingang, vom Bahnhof sind es zehn Minuten zu Fuss. Wer etwas Grosses kauft, bekommt vom Verkäufer einen Passierschein für die Ladezone hinter der Halle. Hunde bleiben draussen.$t$),
  ($t$brocante-de-misery$t$, 'de', $t$Seit 2007 füllt die Brocante de Misery an einem Septemberwochenende den Dorfplatz und die Turnhalle von Misery bei Freiburg. Samstag 9 bis 18 Uhr, Sonntag 9 bis 17 Uhr. Organisiert vom Verein Brocante des Amis, der auch die Brocante am Quai de Nogent in Yverdon veranstaltet. Misery liegt zehn Autominuten nordwestlich von Freiburg; mit dem Bus ab Freiburg bis Misery, village.$t$),
  ($t$brocante-de-rive-nyon$t$, 'de', $t$Diese Brocante zieht sich durch Nyons Quartier de Rive und die Quais am See entlang und hat schon über vierzig Ausgaben hinter sich. Organisiert wird sie vom Quartierverein selbst, der Association pour l'animation du Quartier de Rive. Den Rest des Jahres führt derselbe Verein die Puces de Nyon durch, einen Flohmarkt einmal im Monat.$t$),
  ($t$brocante-locarno$t$, 'de', $t$Am Wochenende von Christi Himmelfahrt füllt die Brocante Locarno die Gassen der Città Vecchia: Antiquitäten, Mid-Century-Stücke, Vintage und Design, alles mindestens 20 Jahre alt – das ist Vorschrift. Freitag und Samstag von 10 bis 19 Uhr, bei jedem Wetter, seit 2026 organisiert vom Verein Pro Città Vecchia. Am Samstag verkaufen daneben Kinder auf der Piazza San Francesco ihre eigenen Sachen. Vom Bahnhof Locarno sind es zehn Minuten zu Fuss.$t$),
  ($t$brocante-lutry$t$, 'de', $t$Die Brocante läuft drei Tage lang auf den Quais am See.$t$),
  ($t$brocante-vide-grenier-55-plus-ecublens$t$, 'de', $t$Der Verein 55+ d'Ecublens, Freiwillige für die über 55-Jährigen der Gemeinde, organisiert diesen Markt: Brocante und Vide-grenier in einem. Laut Flyer wird alles günstig verkauft. Es gibt eine Bar mit Erfrischungen, und alle sind willkommen.$t$),
  ($t$brocantissima-morges$t$, 'de', $t$Hier baut nicht jeder Händler einfach auf: Man bewirbt sich, und der Veranstalter wählt aus. Angekündigt sind Raritäten, Eleganz und signierte Stücke.$t$),
  ($t$chilbi-flohmarkt-glarus$t$, 'de', $t$Der Chilbi-Flohmarkt Glarus findet an einem Samstag im August rund ums Rathaus statt, von 8 bis 16 Uhr, als Teil der Glarner Chilbi. Kinder und Jugendliche bis 16 verkaufen gratis auf einer Decke oder an einem Gratisstand, Erwachsene mieten einen Stand; anmelden muss man sich. Das Rathaus liegt fünf Minuten vom Bahnhof entfernt.$t$),
  ($t$coffre-ouvert-monthey$t$, 'de', $t$Coffre ouvert Monthey ist ein Kofferraum-Flohmarkt mitten in der Stadt: Privatverkäuferinnen und Privatverkäufer bieten aus dem Auto und vom Tisch an, rund 100 Stände, jeden ersten Samstag im Monat von April bis November, 9 bis 17 Uhr – im August nicht. Zwei Standorte nebeneinander: der Hof des Vieux-Collège an der Avenue de la Gare 17 und die Esplanade du Crochetan. Der Bahnhof Monthey liegt gleich daneben.$t$),
  ($t$coffre-ouvert-villeneuve$t$, 'de', $t$Coffre Ouvert ist in vier Zonen aufgeteilt. «Gare» liegt entlang des Parkplatzes zwischen Post und Bahnhof, «Lac» am See, «Marronniers» unter den Kastanienbäumen, und im «Vide-Dressing» gibt es nur Kleidung und Modeaccessoires. Private und Profis stehen nebeneinander, mit Antiquitäten, Möbeln, Büchern, Spielsachen, Kunst und Sammlerstücken. Neuware zum Weiterverkauf ist in den Zonen der Privaten nicht erlaubt. Den Markt gibt es seit über zehn Jahren. Parken kannst du gleich in der Nähe, auf der Bahnseite.$t$),
  ($t$elbeflohmarkt-dresden$t$, 'de', $t$Jeden Samstag von Ende Januar bis Ende November am Elbufer unterhalb der Albertbrücke. Händler und private Verkäufer bieten Antiquitäten, Raritäten, Haushaltswaren, Second-Hand-Kleidung und Dinge aus DDR-Zeiten an. Eintritt frei; Tram 6 und 13 halten am Güntzplatz, kostenlose Parkplätze gibt es gegenüber an der Wigardstraße.$t$),
  ($t$enter-flohmarkt-derendingen$t$, 'de', $t$Der Enter Flohmarkt findet etwa einmal im Monat in der Eventhalle der Technikwelt Enter in Derendingen bei Solothurn statt – drinnen, dazu ein Kofferraum-Bereich draussen. Hausrat, Möbel, Kleidung, Spielzeug, Antikes, Technik, Instrumente, Schallplatten, Bücher, Werkzeug; Eintritt frei, das Enter-Restaurant ist offen. Samstags von 10 bis 17 Uhr, ab 2027 bis 16 Uhr. Ab Bahnhof Derendingen zehn Minuten zu Fuss.$t$),
  ($t$enter-retrotechnikmarkt-derendingen$t$, 'de', $t$Ein Markt für historische Technik, auf dem Privatpersonen und Firmen Sammlerstücke, Gebrauchtwaren und Liquidationsware anbieten, für Sammler, Handwerker und Bastler. Maschinen und Apparate aller Art: Dampfmaschinen, Motoren, Mess- und medizinische Instrumente, Uhren, Haushaltsgeräte, Musik- und Spielautomaten. Dazu Radios, Fernseher, Tonbandgeräte, Plattenspieler, Schreibmaschinen und Computer, Werkzeuge, Ersatzteile und technische Literatur. Es gibt 500 kostenlose Parkplätze, die Haltestelle Derendingen, Freiheit liegt fünf Minuten zu Fuss entfernt.$t$),
  ($t$fete-de-la-brocante-le-landeron$t$, 'de', $t$Am letzten Septemberwochenende verwandelt die Fête de la Brocante den mittelalterlichen Bourg von Le Landeron, zwischen Bielersee und Jura, in einen grossen Antik- und Trödelmarkt. Drei Tage: Freitag 12 bis 19 Uhr, Samstag 9 bis 19 Uhr, Sonntag 9 bis 18 Uhr. Organisiert vom Verein der Altstadt (AVVL). Der Bahnhof Le Landeron liegt zehn Gehminuten entfernt.$t$),
  ($t$floh-raritaetenmarkt-europaplatz-bern$t$, 'de', $t$Floh- und Raritätenmarkt auf dem Europaplatz in Bern. Privatverkäufer und Händler bieten Antiquitäten, Raritäten und Secondhand-Waren aller Art an.$t$),
  ($t$floh-und-antiquitaetenmarkt-schadaumaerit-thun$t$, 'de', $t$Fast dreissig Jahre lang füllte Thuns Flohmarkt den Mühleplatz, bis der Andrang so gross war, dass der Aufbau regelmässig die Notfallachse blockierte. 2020 verlegte ihn die Stadt hierher, zum Schadaumärit, der privat organisiert wird. Die Schadaugärtnerei ist die ehemalige Gärtnerei beim Schadaupark, heute eine Zwischennutzung für Kultur, Sport und Quartierleben, koordiniert von der Stadt. Auf den Tischen: Antiquitäten und allerlei Secondhand.$t$),
  ($t$flohmaert-zueg-ond-sache-beromuenster$t$, 'de', $t$Der Flohmärt «Züg ond Sache» in Beromünster findet einmal im Jahr zur Kilbi statt, im Festsaal und in der Schol des Stiftstheaters – drinnen. Kleidung, Antikes, Hausrat und mehr an reservierten Tischen; Einheimische können gut erhaltene Sachen spenden, die das Team für das Projekt verkauft. Mit dem Bus ab Luzern oder Sursee bis Beromünster, Stift.$t$),
  ($t$flohmarkt-aarau$t$, 'de', $t$Hinter diesem Markt steht Kramer, ein Secondhand-Betrieb; seine Läden in Aarau und Lenzburg werden mehrheitlich ehrenamtlich geführt, der Gewinn geht an Sozial- und Umweltprojekte im Kanton. Die Stände füllen die Markthalle und ziehen sich über den Färberplatz. Auf der Flohmi-Wiese verkaufen Leute von der Decke aus und kommen und gehen, wann sie wollen. Die Flohmi-Bühne ist offen für alle, die ein Instrument mitbringen.$t$),
  ($t$flohmarkt-ace-cafe-rothenburg$t$, 'de', $t$Ein Flohmarkt im Ace Cafe Luzern, einem Café, in dem das ganze Jahr über Auto- und Motorradtreffen stattfinden. Morgens serviert die Küche Frühstück.$t$),
  ($t$flohmarkt-altdorf$t$, 'de', $t$Der Flohmarkt Altdorf ist der Flohmarkt der Gemeinde auf dem Lehnplatz mitten im Dorf, zweimal im Jahr an einem Samstag im Mai und im September, 8 bis 16 Uhr: Gebrauchtes, Kurioses, Schnäppchen – Feilschen gehört dazu. Vom Bahnhof Altdorf sind es zehn Minuten zu Fuss ins Zentrum.$t$),
  ($t$flohmarkt-alte-holzbruecke-olten$t$, 'de', $t$Der Flohmarkt auf der alten Holzbrücke ist ein Wahrzeichen von Olten: Die Stände stehen auf der gedeckten Holzbrücke über die Aare, mitten in der Stadt, von März bis Oktober jeweils am letzten Samstag im Monat, 7.30 bis 17 Uhr. Die Brücke liegt drei Minuten vom Bahnhof Olten entfernt.$t$),
  ($t$flohmarkt-am-arkonaplatz-berlin$t$, 'de', $t$Jeden Sonntag von 10 bis 17 Uhr auf einem Platz mitten im Wohnviertel zwischen Rosenthaler Platz und Mauerpark. Bis zu 100 Händler mit Antiquitäten, Vintage-Kleidung, Kunsthandwerk und Kuriositäten. Kleiner und ruhiger als der Mauerpark nebenan; am Totensonntag Ende November geschlossen.$t$),
  ($t$flohmarkt-arbon$t$, 'de', $t$Der Flohmarkt Arbon findet in der Regel am zweiten Samstag im Mai, Juni und September auf dem Fischmarktplatz am Bodensee statt, von 8 bis 16 Uhr, organisiert von der Stadt. Raritäten, Kurioses, Kitsch und Brauchbares – die Altstadt liegt gleich daneben. Vom Bahnhof Arbon sind es fünf Minuten zu Fuss.$t$),
  ($t$flohmarkt-arlesheim$t$, 'de', $t$Der Arleser Flohmärt verwandelt einmal im Jahr den Dorfkern von Arlesheim in einen Flohmarkt: an einem Samstag im August, 9 bis 16 Uhr, mit gesperrten Strassen rund um den Dorfplatz. Organisiert vom Verein Flohmarkt Arlesheim; anmelden kann man sich nur per E-Mail. Mit der Tram 10 ab Basel bis Arlesheim Dorf.$t$),
  ($t$flohmarkt-barfuesserplatz-basel$t$, 'de', $t$Die Fachstelle Messen und Märkte des Kantons führt diesen Markt, und die erste Regel ist einfach: Verkauft wird nur, was als gebraucht erkennbar ist. Für Essen und Getränke braucht es eine eigene Genehmigung. Die Ware liegt auf Tischen; nur bei den fest montierten Sitzbänken darf sie auf dem Boden ausgelegt werden. Braucht eine grössere Veranstaltung den Platz, fällt der Flohmarkt aus. Parkhäuser: City-Parkhaus beim Universitätsspital, Steinen oder Elisabethen.$t$),
  ($t$flohmarkt-buelach-stadthalle$t$, 'de', $t$Das Veranstaltungsteam der Stadt führt den Markt in der Stadthalle durch, die Platz für 80 Stände bietet. Im Frühling und im Herbst kommen draussen zusätzliche Stände dazu. Einen kleinen Stand mit Essen und Getränken gibt es auch.$t$),
  ($t$flohmarkt-burstelpark-frauenfeld$t$, 'de', $t$Der Flohmarkt im Burstelpark ist der Stadtflohmarkt von Frauenfeld: von April bis Oktober jeweils am zweiten Samstag im Monat, 8 bis 16 Uhr, im Park an der Thundorferstrasse gleich hinter dem Alterszentrum. Die Stadt teilt die Plätze zu, Anmeldung bis Donnerstag. Kostenlos parken kannst du beim Rüegerholz; vom Bahnhof sind es zehn Minuten zu Fuss.$t$),
  ($t$flohmarkt-chilbiplatz-duebendorf$t$, 'de', $t$Die Ludothek Dübendorf, die Spielzeugausleihe der Stadt, führt diesen Markt zweimal im Jahr auf dem Chilbiplatz durch. Auf den Tischen: Schmuck, Kleidung, Spielsachen, Elektronik und was sonst noch auftaucht. Der Platz ist für den Verkehr gesperrt, parken dürfen dort nur die Standbetreiber – komm also mit dem Zug oder dem Fahrrad. Am Stand der Organisatoren gibt es Kaffee, hausgemachten Kuchen, Hot Dogs, Bier und Softdrinks.$t$),
  ($t$flohmarkt-citti-park-luebeck$t$, 'de', $t$Etwa einmal im Monat sonntags von 8.30 bis 16 Uhr auf dem Gelände des CITTI-PARK in Buntekuh. Überdachte Plätze sind möglich; Hot Dogs, Currywurst, Kaffee und Kuchen gibt es vor Ort. Parkplätze am Einkaufszentrum; der Bus 11 vom Hauptbahnhof hält in Buntekuh.$t$),
  ($t$flohmarkt-daglfing-muenchen$t$, 'de', $t$Direkt neben der Trabrennbahn Daglfing, dazu ein Antikmarkt unter alten Bäumen mit überdachtem Bereich. Neben Antiquitäten gibt es Spielzeug, Kinderkleidung und Babysachen, dazu etwas Neuware und Essen. Bei Regen hat das Antikhaus auf dem Gelände ein Restaurant und ein Café. Der Bus 183 fährt alle 20 Minuten zur Trabrennbahn, ab S8 Daglfing, U4 Arabellapark und U2 Messestadt West; es gibt über 2000 Parkplätze.$t$),
  ($t$flohmarkt-dampfzentrale-bern$t$, 'de', $t$Markt rund um das Kulturzentrum Dampfzentrale an der Aare: Vintage-Kleidung, Designobjekte, Bücher und Secondhand, am letzten Sonntag des Monats von April bis September, bei jedem Wetter. Eintritt frei; organisiert vom Zentralmarkt.$t$),
  ($t$flohmarkt-dorfplatz-horgen$t$, 'de', $t$Der Flohmi auf dem Dorfplatz Horgen findet fünfmal im Jahr im und ums Dorfplatz-Zelt statt, samstags von 9 bis 16 Uhr, organisiert vom Verein Dorfchärn. Kunst, Secondhand, Spielzeug und Kleidung. Kaffee, Kuchen und Grillwurst gibt es vor Ort. Das Parkhaus unter dem Platz hat einen Lift direkt nach oben; vom Bahnhof Horgen sind es fünf Minuten.$t$),
  ($t$flohmarkt-eiszentrum-luzern$t$, 'de', $t$Das gedeckte Aussenfeld des Eiszentrums Luzern wird zum Flohmarkt, bei jedem Wetter: Bücher, Spielsachen, Vintage-Fundstücke und Kuriositäten. Eintritt frei, Grillstand vor Ort, gut mit öffentlichen Verkehrsmitteln erreichbar.$t$),
  ($t$flohmarkt-grosse-halle-bern$t$, 'de', $t$Jeden ersten Sonntag im Monat findet in und um die Grosse Halle (Schützenmattstrasse 7) ein grosser Flohmarkt statt – direkt beim Hauptbahnhof. Möbel, Kleidung, Bücher, Vinyl, Werkzeug und Kuriositäten aller Art. Ausser im Januar und August.$t$),
  ($t$flohmarkt-gz-hirzenbach$t$, 'de', $t$Ein Flohmarkt für Kindersachen: Kleidung, Bücher, Spielsachen und Krimskrams. Der Markt findet im grossen Saal des GZ statt, in den Sommermonaten draussen. Alle verkaufen ihre eigenen Sachen, und durchgeführt wird er erst, wenn sich mindestens zehn Verkäuferinnen und Verkäufer angemeldet haben.$t$),
  ($t$flohmarkt-gz-seebach$t$, 'de', $t$Niemand meldet sich an, niemand zahlt für den Platz: Man bringt eine Decke und einen Klappstuhl mit und breitet seine Sachen vor dem Provisorium des GZ aus. Tauschen geht hier genauso wie Kaufen. Das Café des GZ ist offen.$t$),
  ($t$flohmarkt-hinwil$t$, 'de', $t$Zum Markt gehört ein eigenes Café, das Flohmibeizli, mit Mittagsmenü. Für die Musik sorgt DJ Gummistiefel.$t$),
  ($t$flohmarkt-koelner-altstadt-koeln$t$, 'de', $t$Der Markt findet an einzelnen Wochenenden vom Frühjahr bis in den Herbst auf der Rheinpromenade in der Altstadt statt. Über 150 Händler und private Verkäufer aus Deutschland und den Nachbarländern bieten Antiquitäten und Gebrauchtes an; Neuware ist verboten. Den Markt gibt es seit über 50 Jahren.$t$),
  ($t$flohmarkt-lenzburg-metzgplatz$t$, 'de', $t$Ein Flohmarkt unter freiem Himmel auf dem Metzgplatz in Lenzburg, dreimal im Jahr: Bücher, Kleidung, Deko und Spielsachen von Verkäuferinnen und Verkäufern aus der Gegend.$t$),
  ($t$flohmarkt-liestal$t$, 'de', $t$Der Flohmärt Liestal füllt zweimal im Jahr die Altstadt: Zeughausplatz, Rosengasse und Kanonengasse, an einem Samstag im April und einem im September, 8 bis 15 Uhr, rund 100 Stände. Organisiert wird er vom Verein IG Flohmarkt im Auftrag der Stadt; die Ware liegt auf Tischen, nicht am Boden. Vom Bahnhof Liestal sind es fünf Minuten zu Fuss.$t$),
  ($t$flohmarkt-mall-of-switzerland-ebikon$t$, 'de', $t$Flohmarkt auf dem Ebisquare der Mall of Switzerland in Ebikon: Keller und Dachboden räumen und alten Sachen ein zweites Leben geben – oder durch die Stände gehen und finden, was man schon lange sucht. Eintritt frei.$t$),
  ($t$flohmarkt-malters$t$, 'de', $t$Der Flohmarkt Malters ist der Herbstflohmarkt der Elterngruppe im Gemeindesaal an der Bahnhofstrasse – drinnen, auf zwei Etagen, mit einem kostenlosen Deckenflohmarkt für Kinder im Obergeschoss. Gebrauchtes und Selbstgemachtes; Hunde bleiben draussen. Der Saal liegt gleich beim Bahnhof Malters.$t$),
  ($t$flohmarkt-nippes-koeln$t$, 'de', $t$Ein Trödel- und Sammlermarkt, der mehrmals im Jahr auf dem Wilhelmplatz mitten in Nippes stattfindet. Mehr als 150 Händler bieten Antiquitäten und Gebrauchtes an; Neuware ist nicht erlaubt. Die Strassenbahnlinien 12 und 15 halten an der Florastraße.$t$),
  ($t$flohmarkt-obere-muehle-duebendorf$t$, 'de', $t$Die Stände stehen auf dem Kiesplatz des Kulturzentrums Obere Mühle, unter den Bäumen an der Glatt. Zu finden sind Kleidung, Einrichtung, Spielsachen, Bücher, CDs und Elektronik. Die KulturBar öffnet, bevor der erste Stand verkauft, und über Mittag gibt es Essen vom Grill.$t$),
  ($t$flohmarkt-oetwil-am-see$t$, 'de', $t$Der Verein Märtlüüt führt den Markt und gleich auch den Verpflegungsstand – darum dürfen die Verkäufer keine Esswaren anbieten. Neues kommt nicht auf die Tische; gewünscht ist, was brauchbar, ansprechend, ausgefallen, antik oder modern ist. Parke beim Gemeindehaus, nicht beim Volg: Dort drohen Bussgelder bis 200 Franken.$t$),
  ($t$flohmarkt-olympiapark-muenchen$t$, 'de', $t$Freitags und samstags von 7 bis 15.30 Uhr auf der Parkharfe des Olympiaparks, ab Parkblock 5. Wer verkaufen will, kommt einfach vorbei; ein Tisch kostet 12 bis 15 Euro. An Feiertagen und bei grossen Veranstaltungen im Park fällt der Markt aus. Veranstalter ist das Bayerische Rote Kreuz, Kreisverband München.$t$),
  ($t$flohmarkt-papieriplatz-cham$t$, 'de', $t$Der Flohmarkt auf dem Papieriplatz findet zweimal im Jahr vor dem Langhuus statt, der Kulturfabrik auf dem alten Papieri-Areal in Cham. Sonntags von 10 bis 15 Uhr verkaufen Privatpersonen auf Plätzen von rund neun Quadratmetern. Die Bar im Langhuus ist geöffnet, mit Getränken, Kuchen und einem einfachen Mittagessen. Vom Bahnhof Cham sind es zehn Minuten zu Fuss.$t$),
  ($t$flohmarkt-paulusheim-luzern$t$, 'de', $t$Flohmarkt für Kinderkleidung, Spielsachen sowie Baby- und Kinderartikel im Paulusheim in Luzern, zweimal im Jahr – im Frühling und im Herbst. Tische können einen Monat im Voraus per Mail reserviert werden. Für Besucherinnen und Besucher ist der Eintritt frei.$t$),
  ($t$flohmarkt-petersplatz-basel$t$, 'de', $t$Wöchentlicher Flohmarkt neben der Peterskirche und der Universität, jeden Samstag. Rund 300 Verkäuferinnen und Verkäufer verteilen sich über den Platz: am einen Ende gute Antiquitäten und Vintage-Deko, am anderen Kinderkleidung und günstige Haushaltswaren. So gemischt ist auch das Publikum – Sammler, Studierende, Touristen, Stammgäste und Wiederverkäufer –, und Feilschen gehört dazu. Der Markt findet bei jedem Wetter statt, ausser an Feiertagen und in der Woche der Herbstmesse.$t$),
  ($t$flohmarkt-rathausplatz-wettingen$t$, 'de', $t$Flohmarkt auf dem Rathausplatz in Wettingen, monatlich von März bis November: Haushaltswaren, Spielsachen, Kleidung und Bücher von Verkäuferinnen und Verkäufern aus der Gemeinde. Familiär und lokal.$t$),
  ($t$flohmarkt-rheinaue-bonn$t$, 'de', $t$An einem Samstag im Monat von April bis Oktober, 8 bis 18 Uhr, im Rheinauenpark. Nur Gebrauchtes und Kunsthandwerk, keine Neuware; Autos bleiben draussen, Sackkarren sind erlaubt. Eintritt frei; Bus 610, 611, 631 und Tram 66/68, Parkplätze am Posttower und an der Ludwig-Erhard-Allee.$t$),
  ($t$flohmarkt-rheinenergiestadion-koeln$t$, 'de', $t$Ein Floh- und Antikmarkt auf dem Vorplatz an der Rückseite des RheinEnergieStadions, gegenüber der Jahnwiese, mehrmals im Jahr. Angeboten werden Antiquitäten und Trödel, Neuware ist verboten; Stände gibt es drinnen und draussen. Parken ist an der Jahnwiese und auf P7 kostenlos, die Linie 1 hält am Stadion.$t$),
  ($t$flohmarkt-rudolf-steiner-schule-basel$t$, 'de', $t$Der jährliche Flohmarkt der Rudolf Steiner Schule Basel findet an einem ganzen Wochenende im April auf dem Schulgelände am Jakobsbergerholzweg statt. Ein klassischer Schulflohmarkt mit treuer Stammkundschaft aus der Umgebung: zwei Tage lang stöbern in Kleidung, Büchern, Spielsachen und Haushaltswaren, in entspannter Atmosphäre im Basler Bruderholz-Quartier.$t$),
  ($t$flohmarkt-rueticenter-pratteln$t$, 'de', $t$Die Organisatoren nennen ihn noch immer «Dr Flohmi ufm Dach», den Flohmarkt auf dem Dach. Er hat vor rund dreissig Jahren klein angefangen und verteilt sich heute auf drei Stockwerke des Rüticenter-Parkhauses, alles überdacht und ohne Autos bei den Ständen. Essen gibt es bei CC Prodega im Erdgeschoss neben den Liften: Croissants, Kuchen, Sandwiches, Hähnchen-Hotdogs, Cervelat und Bratwurst. Ab Bahnhof Pratteln fährt der Bus 83 bis Pratteln Rankacker, und gleich in der Nähe am Rütiweg parkst du kostenlos.$t$),
  ($t$flohmarkt-schlieren-herbstmarkt$t$, 'de', $t$Hier verkaufen Schlieremer Schulkinder ihre alten Spielsachen und Bücher, ausgelegt auf Plastikplanen. Die Kulturkommission Schlieren organisiert den Markt und legt den Platz im Zentrum jedes Jahr neu fest. Bei Regen zieht der Kinderflohmarkt in die Tiefgarage beim Stadthaus. In früheren Jahren lief daneben ein Herbstmarkt mit Apfelchüechli, Zopf, Kunsthandwerk und Infoständen, an denen Schlieremer Vereine ihre Arbeit zeigen.$t$),
  ($t$flohmarkt-schuetzenplatz-braunschweig$t$, 'de', $t$Flohmarkt auf dem Schützenplatz, freitags und samstags ab 6 Uhr früh, seit rund fünfzig Jahren. Schluss ist um 12 oder 14 Uhr, bei Kälte und schlechtem Wetter früher. Eintritt frei, Parken kostet. Von Ende September bis Mitte Oktober belegt die Herbstmesse den Platz.$t$),
  ($t$flohmarkt-seeplatz-waedenswil$t$, 'de', $t$Mit diesem Markt finanziert der Club Interfun, ein Wädenswiler Freizeitverein mit rund 20 Mitgliedern, seine Vereinsaktivitäten mit. Auf dem Seeplatz ist Platz für etwa 40 bis 50 Stände. Verkauft wird nur Gebrauchtes: keine Neuware, keine Restposten, keine Esswaren oder Getränke. Kinder bis 12 dürfen an einem eigenen Stand ihre Spielsachen und Bücher verkaufen.$t$),
  ($t$flohmarkt-st-mangen-quartier$t$, 'de', $t$Jeden letzten Samstag von März bis Oktober werden die Altstadtgassen rund um die Kirche St. Mangen zum Quartierflohmarkt. Rund 100 Stände bieten Vintage-Kleidung, antike Möbel, Bücher und Kuriositäten; organisiert wird er vom Quartierverein St. Mangen.$t$),
  ($t$flohmarkt-suedbruecke-koeln$t$, 'de', $t$Ein Trödel- und Sammlermarkt direkt am Rheinufer unter der Südbrücke in Bayenthal, mehrmals im Jahr. Mehr als 150 Händler bieten Antiquitäten und Gebrauchtes an. Die Strassenbahnlinie 16 hält an der Schönhauser Straße.$t$),
  ($t$flohmarkt-the-stage-liebefeld-bern$t$, 'de', $t$Indoor-Flohmarkt in den VIDMARhallen in Liebefeld bei Bern. Vintage-Mode, Accessoires, Bücher und mehr, in cooler Atmosphäre mit Live-DJ und Essen im le beizli. Die eigene Verkaufsfläche bringst du selbst mit – wer zuerst kommt, mahlt zuerst.$t$),
  ($t$flohmarkt-theaterplatz-baden$t$, 'de', $t$Flohmarkt unter freiem Himmel auf dem Theaterplatz mitten in Baden, an einem Samstag im Monat von Mai bis Oktober: Haushaltswaren, Antiquitäten, Bücher, Deko und Kleidung von Verkäuferinnen und Verkäufern aus der Gegend, mit Cafés rundherum. Eintritt frei.$t$),
  ($t$flohmarkt-ulm-messe$t$, 'de', $t$An einem Wochenende im Jahr füllt sich die Halle der Messe Ulm mit Gebrauchtem — Neuware ist nicht erwünscht. Samstag und Sonntag, jeweils von 10 bis 16 Uhr. Die Stände müssen vorab gebucht werden; der kleinste misst zwei Meter.$t$),
  ($t$flohmarkt-uster-stadthausplatz$t$, 'de', $t$Diesen Markt führt die Stadt selbst: Die Stadtpolizei Uster teilt jeden Platz zu. 50 bis 80 Verkäuferinnen und Verkäufer bauen auf – an Marktständen, die die Stadt vermietet, oder mit eigenem Tisch unter den Arkaden. Die Regel ist kurz: nur Sachen, die sichtbar gebraucht sind. Keine Restposten, keine Fälschungen.$t$),
  ($t$flohmarkt-vogesenplatz-basel$t$, 'de', $t$Kleiner Flohmarkt jeden Samstag auf dem Vogesenplatz im Basler Quartier St. Johann: Gebrauchtes für den Alltag – Kleidung, Bücher, Platten, Spielsachen, Fahrräder, Haushaltswaren –, neben dem Wochenmarkt auf demselben Platz und mit Cafés rundherum. Ruhiger und weniger touristisch als der Petersplatz; eher für die Nachbarschaft als für ernsthafte Sammler.$t$),
  ($t$flohmarkt-weinfelden$t$, 'de', $t$Der Flohmarkt Weinfelden findet von März bis Oktober jeweils am letzten Samstag im Monat auf dem Marktplatz statt – im September nicht –, von 7 bis 16 Uhr, mit einem Marktcafé. Der Marktplatz liegt mitten im Städtchen, fünf Minuten vom Bahnhof.$t$),
  ($t$flohmarkt-wetzikon$t$, 'de', $t$Grosser Flohmarkt im Freien bei der Eishalle in Wetzikon, mit rund 10'000 Quadratmetern Verkaufsfläche. Privatleute bringen alles mit: Möbel, Haushaltswaren, Kleidung, Hobbysachen und grössere Posten, die in keinen Stand in der Innenstadt passen würden. Regional, gemächlich und gross genug für einen ganzen Vormittag.$t$),
  ($t$flohmarkt-winterthur-altstadt$t$, 'de', $t$Floh- und Trödelmarkt in der Fussgängerzone der Winterthurer Altstadt: Haushaltswaren, Bücher, Antiquitäten, Kleidung und Vintage-Deko von Verkäuferinnen und Verkäufern aus der Gegend – eher für Familien, Studierende und Leute aus der Nachbarschaft als für Fachhändler.$t$),
  ($t$flohmarkt-zofingen$t$, 'de', $t$Flohmarkt in der Altstadt von Zofingen: Haushaltswaren, Kleidung, Bücher, Spielsachen und Vintage-Stücke von Verkäuferinnen und Verkäufern aus der Gegend – eher für Familien und Leute aus dem Ort als für Sammler.$t$),
  ($t$flohmaxx-stadthafen-schwerin$t$, 'de', $t$Sonntags von 10 bis 16 Uhr am Stadthafen, mitten in Schwerin. Eintritt und Parken sind frei, und der Markt findet bei jedem Wetter statt. Verkaufen kann jeder: Die Plätze werden ab 6 Uhr ohne Anmeldung vergeben – wer zuerst kommt, mahlt zuerst.$t$),
  ($t$flohmi-bullingerhof-zuerich$t$, 'de', $t$Die Mitglieder des Vereins Lebendiger Bullingerhof führen diesen Markt selbst durch, das Café inklusive: Im Flohmicafé gibt es Kaffee und Kuchen, Gipfeli, Wienerli mit Brot und Getränke. Erlaubt ist nur Gebrauchtes – nichts Neues, keine Restposten, Handys und Schmuck nur als Einzelstücke. Kinder dürfen ihre Spielsachen hier auch ohne Erwachsene verkaufen. Auf dem ganzen Areal gilt während des Markts Fahr- und Parkverbot, und Hunde gehören an die kurze Leine.$t$),
  ($t$flohmi-muttenz$t$, 'de', $t$Einen Marktplatz gibt es nicht: In ganz Muttenz verkaufen die Leute vor der eigenen Haustür, im Garten oder drinnen im Haus oder in der Wohnung. Eine Standkarte auf der Website der Organisatorin zeigt alle, die sich angemeldet haben; die Verkaufenden sollen ihren Stand mit dem Flyer und Ballons kennzeichnen. Eine Muttenzerin hat den Flohmi 2020 gestartet und organisiert ihn seither jedes Jahr; inzwischen sind es über 200 Stände. Verkauft werden darf alles, was legal ist – der Flyer nennt Möbel, Kleidung, Deko und Fahrräder. Die Organisatorin bittet, zu Fuss oder mit dem Fahrrad zu kommen.$t$),
  ($t$flohmi-schmittiplatz-pratteln$t$, 'de', $t$Auf den Tischen liegen Gebrauchtwaren, Kleinantiquitäten und Spielsachen; Neuware ist nicht erlaubt. Die Marktordnung verlangt Preise, bei denen du noch feilschen kannst, und Gratiskisten dürfen erst ab 14 Uhr hingestellt werden. Der Markt findet bei jedem Wetter statt. Für Kaffee und Essen sorgen das Kaffi Schmittiplatz und die Bäckerei Finkbeiner. Vier öffentliche Toiletten stehen hinter dem Schulhaus gegenüber dem Restaurant Schlossgarten, weitere im Kaffi. Von Basel fährt die Tram 14 bis zur Endstation Pratteln; von dort geht es Richtung Schloss. Wer mit dem Auto kommt, parkt beim Kultur- und Sportzentrum Kuspo.$t$),
  ($t$flohmii-galgenen$t$, 'de', $t$Der Flohmii Galgenen ist ein privat organisierter Flohmarkt im Freien auf dem Arthur-Weber-Areal in Galgenen in der March, samstags von 9 bis 16 Uhr und bei jedem Wetter. Es gibt Kleidung, Accessoires, Modeschmuck, Kindersachen, Spielzeug, Deko und Bücher – Feilschen erlaubt. Kinder verkaufen kostenlos auf zwei mal zwei Metern. Kostenlose Parkplätze hinter dem Diga-Gebäude; vom Bahnhof Siebnen-Wangen 15 Minuten zu Fuss.$t$),
  ($t$flohschanze-hamburg$t$, 'de', $t$Jeden Samstag von 8 bis 16 Uhr gegenüber dem U-Bahnhof Feldstraße im Karolinenviertel. Floh- und Antikmarkt ohne Neuware, auf freien Plätzen, unter Pavillons und in der Halle, bei jedem Wetter. Restplätze werden ab 7 Uhr vor Ort vergeben; kostenlose Parkplätze an der Glacischaussee, fünf Minuten zu Fuss.$t$),
  ($t$flosch-schwamendingen-zuerich$t$, 'de', $t$Die Stände verteilen sich auf und um den Schwamendingerplatz, organisiert vom FLOSCH Verein. Jeder Artikel muss angeschrieben sein, und an jedem Stand stehen Name und Wohnort der Verkäuferin oder des Verkäufers – die Marktpolizei kontrolliert. Keine Neuware, keine Billig- und Massenware, und an den Ständen wird nichts zu essen oder zu trinken verkauft. Gratis- und Billigware kommt erst ab halb vier auf den Tisch. Der Markt findet bei jedem Wetter statt; auf und neben dem Marktareal darf nicht geparkt werden.$t$),
  ($t$folie-flea-market-lausanne$t$, 'de', $t$Das Café Folie Voltaire veranstaltet diesen kleinen Markt mit Flohmarktfunden, Secondhand-Kleidung und Handwerk auf der Esplanade unter seinen Kastanienbäumen. Das Café steht in einem historischen Kiosk mitten im Parc Mon-Repos und serviert Kaffee, Tee und kalte Getränke; laut Lausanne Tourisme gibt es auch Crêpes und hausgemachtes Eis, und gleich daneben liegt ein Spielplatz. Im Park stand einst ein Theater, in dem Voltaire zu Gast war – daher der Name des Cafés.$t$),
  ($t$fundus-flohmarkt-arena-root$t$, 'de', $t$Der fundus Flohmarkt füllt die grosse Halle der ARENA Root: Privatverkäuferinnen und -verkäufer bieten Haushaltswaren, Kleidung, Vintage-Fundstücke und vieles mehr an. Eintritt frei.$t$),
  ($t$gaenggali-markt-chur$t$, 'de', $t$«Gänggali» ist vermutlich mit dem französischen «Quincaillerie» verwandt, also Eisen- und Haushaltswaren – die Stadt Chur zählt den Markt zu ihrem Brauchtum. Händler und Privatleute teilen sich das Arcas und den Platz beim Martinsbrunnen, und auch Kinder verkaufen ihre eigenen Sachen. An den Ständen werden keine Esswaren verkauft. Die nächsten kostenpflichtigen Parkplätze gibt es im Parkhaus Arcas und im Parkhaus Lindenquai.$t$),
  ($t$grenzueberschreitender-flohmarkt-kreuzlingen-konstanz$t$, 'de', $t$Der grenzüberschreitende Flohmarkt verbindet einmal im Jahr Kreuzlingen und Konstanz: rund 1000 Stände entlang der Seestrasse auf der Schweizer Seite und in Klein Venedig auf der deutschen, 24 Stunden am Stück, von Samstag 14 Uhr bis Sonntag 15 Uhr. Am besten mit dem Zug nach Kreuzlingen Hafen – einen Parkplatz zu finden ist an diesem Wochenende aussichtslos.$t$),
  ($t$haerkinger-flohmi$t$, 'de', $t$Der Härkinger Flohmi findet drinnen statt, das Wetter spielt also keine Rolle. Auf den Tischen: Antiquitäten und Raritäten, Altes und Neues, auch Selbstgemachtes. Dazu gibt es ein kleines Café mit Snacks zu günstigen Preisen.$t$),
  ($t$hallenflohmarkt-aadorf$t$, 'de', $t$Marktfieber organisiert diesen Hallenflohmarkt im Gemeindezentrum. An den Ständen gibt es Gebrauchtes und Handgemachtes.$t$),
  ($t$hallenflohmarkt-arboldswil$t$, 'de', $t$Drinnen, in der Mehrzweckhalle des Dorfs. Am selben Tag findet nebenan in der Hofmet-Schüüre ein Herbstmarkt mit regionalen Produkten statt, und in der Turnhalle gibt es Mittagessen, Kuchen und Getränke. Parken kannst du direkt bei der Halle.$t$),
  ($t$hallenflohmarkt-hoelstein$t$, 'de', $t$Das Team hinter diesem Markt war jahrelang selbst auf Flohmärkten unterwegs, als Käufer und als Verkäufer, und fand im Waldenburgertal und im Fünflibertal nur wenige – zudem war für den eigenen Garagenflohmarkt kein Platz mehr. Heute füllt der Markt die Mehrzweckhalle Rübmatt: 65 Tische drinnen und 12 draussen, alle von den Organisatoren aufgestellt. Waren dürfen höchstens 10 cm über die Tischkante hinausragen, damit die Gänge auch für Rollstühle frei bleiben. Essen und Getränke gibt es am Buffet; dort findest du auch die Organisatoren – oder du hältst Ausschau nach den grünen T-Shirts. Die Parkplätze vor dem Schulhaus sind für Besucherinnen und Besucher reserviert; am Strassenrand zu parken ist in Hölstein verboten.$t$),
  ($t$hallenflohmarkt-markthalle-basel$t$, 'de', $t$Der Flohmarkt steht unter der grossen Kuppel der Markthalle, zwei Gehminuten vom Bahnhof SBB. Auf den Tischen: Kleidung, Kindersachen, Design- und Alltagsobjekte und kleine Kuriositäten. Die Foodstände der Halle sind gleich nebenan, haben aber je eigene Öffnungszeiten. Die Halle ist weitgehend stufenlos, mit rollstuhlgerechter Toilette und Wickeltisch; Hunde sind an der Leine willkommen. Die Tramhaltestelle «Markthalle» (Linien 1, 2, 8 und 16) liegt vor dem Haupteingang, die Parkhäuser Elisabethen, Steinenparking und Bahnhof SBB sind zu Fuss erreichbar. In derselben Halle gibt es auch einen Nachtflohmarkt, den Nerd Yard und einen Vinylmarkt.$t$),
  ($t$hallenflohmarkt-uster$t$, 'de', $t$Verkauft werden darf hier nur Gebrauchtes. Im Saal gibt es überall Steckdosen, so kannst du Geräte vor dem Kauf testen. Wer mit dem Auto kommt, parkt auf dem Stadthausplatz, im Parkhaus Iluster oder beim Zeughausareal – direkt beim Saal gibt es keine Plätze mehr.$t$),
  ($t$herbst-flohmarkt-richterswil$t$, 'de', $t$Der Herbst-Flohmarkt Richterswil ist der Flohmarkt der Gemeinde auf dem Wisshusplatz im Dorfzentrum. An den Ständen werden weder Essen noch Getränke verkauft. Vom Bahnhof Richterswil sind es fünf Minuten zu Fuss; Tagesparkkarten gibt es online.$t$),
  ($t$hinterhof-flohmarkt-st-gallen$t$, 'de', $t$Ein kleiner Markt in einem Hinterhof an der Rorschacherstrasse, hinter dem Restaurant Oechsli. Design, Vintage und Retro aus den 1960ern bis 1990ern, Antikes, viel Secondhand-Kleidung und alte Leuchtbuchstaben, dazu ein paar weitere Händler mit kleinen Ständen. Im Garten gibt es Getränke und einen Grill. Der Markt findet bei jedem Wetter statt, der Hof ist stufenlos.$t$),
  ($t$hyper-bazar-la-chaux-de-fonds$t$, 'de', $t$Hyper Bazar verteilt 90 Stände auf fünf Zonen rund um die Place de la Carmagnole. Secondhand-Kleidung hängt in der Passage Guillaume-Ritter, professionelle Händler mit alten Sachen, Büchern und Vintage stehen in der Passage Léopold-Robert. Auf der Place de l'Hôtel de Ville wird direkt aus dem Kofferraum verkauft, auf der Carmagnole selbst räumen Privatleute Alltagsdinge aus, und in der Passage du Centre zeigen Kreative Handgemachtes und kleine Labels. Kinder haben eine eigene Ecke für ihre Spielsachen, dazu gibt es eine offene Bühne. Der Obst- und Gemüsemarkt ist gleich in der Nähe. Vom Parking de la Ronde sind es fünf Minuten zu Fuss; die nächste Bushaltestelle heisst Grande Fontaine.$t$),
  ($t$kids-store-flohmarkt-beromuenster$t$, 'de', $t$Kinderartikel-Flohmarkt in der Mehrzweckhalle Beromünster, organisiert vom Familientreff Beromünster. Zweimal jährlich – im Frühling und im Herbst – werden Kinderkleidung und Spielsachen gekauft und verkauft. Eintritt frei.$t$),
  ($t$kinder-flohmi-schloss-arbon$t$, 'de', $t$Beim Kinder-Flohmi im Schloss Arbon verkaufen Kinder ab vier Jahren, begleitet von einer erwachsenen Person, ihre gebrauchten Spielsachen, Kleidung und Bücher – und finden neue Schätze. Organisiert von der Stadt Arbon mit dem Familienverein.$t$),
  ($t$kinderflohmarkt-gz-bachwiesen$t$, 'de', $t$Hier gibt es nur Kindersachen: gebrauchte Spielsachen und Kinderartikel bis 12 Jahre – keine Haushaltsgegenstände, keine Erwachsenenkleidung, keine Medien ab 16. Kinder und Erwachsene tauschen oder verkaufen. Die Cafeteria des GZ ist während des Flohmarkts geöffnet. Ist Regen angesagt, steht ab Mittag zwei Tage vorher auf der Website des GZ, ob der Markt stattfindet. Beim GZ gibt es keine Parkplätze.$t$),
  ($t$kinderflohmarkt-gz-heuried$t$, 'de', $t$Auf dem Flohmarkt des GZ Heuried liegen Kindersachen auf den Tischen und nichts für Erwachsene. Die kommen anders zum Zug: Zweimal im Jahr veranstaltet dasselbe GZ einen Flohmarkt, auf dem alles für Erwachsene verkauft werden darf.$t$),
  ($t$kinderflohmarkt-gz-hottingen$t$, 'de', $t$Das GZ Hottingen führt diesen Markt zusammen mit dem Quartierverein Hottingen durch. Ein Stand ist ein Bettlaken am Boden oder ein kleiner Tisch, den die Verkäuferinnen und Verkäufer selbst mitbringen.$t$),
  ($t$kinderflohmarkt-gz-schindlergut$t$, 'de', $t$Der Kinderflohmarkt findet im Schindlergut Park statt, einem Stadtpark im Kreis 6 zwischen ETH-Quartier und Unterstrass, beim Gemeinschaftszentrum, das im Quartier «Schigu» heisst. Kinder bringen ein Tuch mit, belegen einen Platz und verkaufen Spielsachen, Bücher und Kleidung — ohne Anmeldung. Nur bei schönem Wetter.$t$),
  ($t$kinderflohmarkt-uster$t$, 'de', $t$Hier verkaufen nur Kinder; Erwachsene kommen zum Kaufen, Stöbern oder Aufpassen. Der Markt liegt kurz vor den langen Sommerferien, und die Stadt wirbt damit, dass sich so die Ferienkasse aufbessern lässt. Ein Teil der Kinder verkauft an überdachten Ständen, die verlost werden; andere kommen einfach mit einem Bündel und breiten es auf einer Wolldecke aus. An einem Stand gibt es kostenloses Eis.$t$),
  ($t$kinderflohmarkt-winterthur-altstadt$t$, 'de', $t$Einmal im Jahr wird die Steinberggasse in der Winterthurer Altstadt zum Kindermarkt. Kinder und Jugendliche verkaufen Spielzeug, Bücher, Kleidung und andere Kindersachen, mitten in der Fussgängerzone der Altstadt.$t$),
  ($t$kinderkleider-spielwaren-flohmarkt-luzern-b102$t$, 'de', $t$Flohmarkt für Kinderkleidung und Spielsachen im Quartierlokal B102 in Luzern – Secondhand für die Kleinen, gut für die Umwelt und das Portemonnaie. An der Bar gibt es Kuchen und Kaffee. Eintritt frei.$t$),
  ($t$kofmehl-flohmi-solothurn$t$, 'de', $t$Der Kofmehl-Flohmi ist der Flohmarkt der Kulturfabrik Kofmehl in Solothurn, unter der Leporello-Brücke direkt neben dem Konzerthaus – seit 1993. An einem Samstag im September, 9 bis 15 Uhr, Eintritt frei; Getränke und Snacks vom Barwagen, ab 11.45 Uhr Mittagessen. Vom Bahnhof Solothurn sind es 15 Minuten zu Fuss.$t$),
  ($t$kreisflohmi-zuerich$t$, 'de', $t$Der Kreisflohmi ist Zürichs Quartierflohmarkt von Bewohnerinnen und Bewohnern für alle: Jeder Stadtkreis hat einen Samstag, an dem in Wohnungen, Innenhöfen, Gärten, Garagen und auf Dachterrassen verkauft wird – nie auf dem Gehweg. Wo genau, zeigt die Karte auf kreisflohmi.ch. Von 11 bis 18 Uhr, bei jedem Wetter; Verkaufen und Besuchen sind kostenlos.$t$),
  ($t$kunst-und-troedelmarkt-fehrbelliner-platz-berlin$t$, 'de', $t$Überdachte Holzstände direkt am U-Bahnhof Fehrbelliner Platz, an denen Privatleute, Profihändler und Künstler nebeneinander verkaufen. Der Markt ist in Gassen aufgeteilt: Porzellan, Silberbesteck und alte Fotografien auf der Antikmeile, Platten, Radios und Lampen aus den Sechzigern und Siebzigern im Trödelkarree, dazu eine Kleidergasse und eine Kunstmeile. Neuware gibt es hier keine.$t$),
  ($t$ladies-flohmarkt-fundus-root$t$, 'de', $t$Abend-Flohmarkt nur für Frauen in der ARENA Root, organisiert von fundus: Kleidung, Schuhe, Taschen und Accessoires, von Frauen für Frauen verkauft, mit Musik – näher an einer Kleidertauschbörse als an einem klassischen Flohmarkt. Die Ausgaben finden unregelmässig statt; Tickets gibt es über die fundus-Website.$t$),
  ($t$les-puces-du-cpo-lausanne$t$, 'de', $t$Hier verkaufen keine einzelnen Händler: Das CPO, das Quartierzentrum von Ouchy, betreibt im Untergeschoss seinen eigenen Secondhand-Raum, gefüllt mit Sachen, die ihm geschenkt werden. Im Angebot: Bücher, Deko, Geschirr, kleine Möbel, Küchenutensilien, Kleidung und Accessoires für Gross und Klein, Kinderausstattung und Spielsachen – aber keine Haushaltsgeräte. Die Puces gehen auf Eugène Roy zurück, einen früheren Leiter des Zentrums, der sie aus sozialem Antrieb gründete. Du räumst zu Hause aus? Gut erhaltene Sachen kannst du direkt bei den Puces abgeben. Stufenlos geht es über die Rampe auf der Rückseite, von der Südseite des Temple de la Croix d'Ouchy her. Die M2 hält bei Délices; öffentliche Parkplätze gibt es beim Hôtel Royal Savoy.$t$),
  ($t$les-puces-du-loup-lausanne$t$, 'de', $t$Einen Stand bekommt nur, wer auf dem Plateau de la Blécherette wohnt – in Bois-Gentil, Bossons, Grattapaille oder den Plaines-du-Loup –, und Profis sind nicht zugelassen. Die Stände stehen rund um die Schule Plaines-du-Loup, und die Restaurants im Quartier sind geöffnet. Der Bus 1 hält bei Bois-Gentil, der Bus 21 bei Grattapaille oder Bossons. Das Parking du Vélodrome ist kostenlos, das Parking du Loup kostenpflichtig.$t$),
  ($t$liesberger-flohmarkt$t$, 'de', $t$Zwei Familien, Kohler und Balmer, haben diesen Markt nach einem Familienbesuch in Liesberg 2009 ins Leben gerufen. Für den ersten Markt hofften sie auf 50 Aussteller – es kamen 86. Die Organisatoren nennen ihn «Antiquitäten Floh- und Buuremärt». Die Stände stehen in der Mehrzweckhalle Seemättli, draussen im Freien und überdacht. Direkt vor der Halle liegt ein grosser Parkplatz, die Postautohaltestelle ist nur wenige Meter entfernt.$t$),
  ($t$luzerner-flohmarkt-voegeligaertli$t$, 'de', $t$Jeden Samstag von Mai bis Oktober findet ein Flohmarkt im Vögeligärtli statt, einem Park in der Luzerner Neustadt, wenige Minuten vom Hauptbahnhof. Antiquitäten, Bücher, Vinyl und Kuriositäten aller Art. Organisiert von der Stadt Luzern, mit klaren Regeln: nur Gebrauchtes, keine Neuware.$t$),
  ($t$maedelsflohmarkt-tanzwerk-101-zuerich$t$, 'de', $t$Kleidung, Schuhe, Taschen, Schmuck, Lingerie und Accessoires – alles gut erhalten, alles Secondhand, alles für Frauen, vom Designerlabel über Vintage bis zum No-Name-Stück. Verkauft wird nur von Privatpersonen: keine Händlerinnen, nichts Handgemachtes. Es gibt Umkleidekabinen, du kannst also zuerst anprobieren. Das Tanzwerk 101 liegt auf der Dachterrasse des Migros-Komplexes: ein grosser Saal mit Bar, Holzboden und Tageslicht, dazu ein kleiner Saal gleich daneben. Die Tram 4 hält bei «Toni-Areal», schräg gegenüber dem Haupteingang; das kostenpflichtige Parkdeck liegt direkt darüber, Einfahrtshöhe maximal 2.20 m. Hunde sind im ganzen Migros-Komplex verboten. Den Markt gibt es seit 2017.$t$),
  ($t$maedelsflohmarkt-xxl-dietikon$t$, 'de', $t$Die XXL-Ausgabe des Mädelsflohmarkts in der Stadthalle Dietikon: Damenmode, Schuhe, Accessoires, Vintage und Designerlabels auf grösserer Fläche, mit Umkleidekabinen. Eher Modeevent als Flohmarkt – kuratiert, gesellig, ganz auf das ausgerichtet, was du wirklich trägst.$t$),
  ($t$mannheimer-krempelmarkt-mannheim$t$, 'de', $t$Sieben Markttage im Jahr auf dem Neuen Messplatz, für Besucher von 8 bis 14 Uhr. Nur Gebrauchtes, keine Neuware; der ganze Platz ist währenddessen Fussgängerzone. Eintritt frei, bei jedem Wetter. Getragen wird der Markt vom gemeinnützigen Verein Projekt Freiraum.$t$),
  ($t$marche-aux-puces-archipel-sion$t$, 'de', $t$Der Marché aux puces von Sitten findet im Innenhof von L'Archipel statt, dem Kulturort an der Rue de l'Industrie 47 – jeden ersten Sonntag im Monat von März bis November, im August nicht, jeweils von 8.30 bis 13 Uhr. Ein Morgenmarkt: Früh kommen lohnt sich. Vom Bahnhof Sitten sind es zehn Minuten zu Fuss Richtung Industriequartier.$t$),
  ($t$marche-aux-puces-fribourg-cathedrale$t$, 'de', $t$Antike Möbel, Grossmutters Porzellan und kleiner Deko-Krimskrams – so fasst das Tourismusbüro von Freiburg diese Brocante in der Altstadt zusammen. Es verkaufen Privatleute wie Profis. Später im Monat gibt es in Freiburg einen zweiten Flohmarkt, auf der Place Georges-Python.$t$),
  ($t$marche-aux-puces-fribourg-place-python$t$, 'de', $t$Der Marché aux puces de Fribourg belebt von März bis November zweimal im Monat die Altstadt. Zu finden sind Brocante, Vintage, Hausrat und kleine Raritäten von 30 bis 50 Ausstellern, je nach Wetter. Diese Ausgabe findet am letzten Samstag des Monats auf der Place Georges-Python statt, oder auf der Place de l Equilibre, wenn diese belegt ist.$t$),
  ($t$marche-aux-puces-jardin-anglais-neuchatel$t$, 'de', $t$Der Eintritt zum Markt im Jardin anglais ist frei. Das Tourismusbüro von Neuenburg zählt alte Bücher, Deko, ausgefallene Gegenstände und Kuriositäten zum Angebot. Neuigkeiten gibt es auf der Facebook-Seite «pucesjardinanglais».$t$),
  ($t$marche-aux-puces-plainpalais-geneve-erster-sonntag$t$, 'de', $t$Der Marché aux puces de Plainpalais ist ein grosser Flohmarkt unter freiem Himmel: Auf der Plaine de Plainpalais mitten in Genf bieten über 300 Stände am ersten Sonntag des Monats Möbel, Antiquitäten, Vintage-Kleidung, Bücher und Sammlerstücke an.$t$),
  ($t$marche-aux-puces-plainpalais-geneve-mittwoch$t$, 'de', $t$Der Marché aux puces de Plainpalais ist ein grosser Flohmarkt unter freiem Himmel: Auf der Plaine de Plainpalais mitten in Genf bieten über 300 Stände jeden Mittwoch Möbel, Antiquitäten, Vintage-Kleidung, Bücher und Sammlerstücke an.$t$),
  ($t$marche-aux-puces-plainpalais-geneve-samstag$t$, 'de', $t$Der Marché aux puces de Plainpalais ist ein grosser Flohmarkt unter freiem Himmel: Auf der Plaine de Plainpalais mitten in Genf bieten über 300 Stände jeden Samstag Möbel, Antiquitäten, Vintage-Kleidung, Bücher und Sammlerstücke an.$t$),
  ($t$marche-aux-puces-vevey$t$, 'de', $t$Der Quartierverein der Place Robin veranstaltet den Markt; sein voller Name, Association pour les Environs de la place Robin, ergibt abgekürzt APERO. Auf dem Platz steht ein Foodtruck.$t$),
  ($t$marche-calabash-lausanne$t$, 'de', $t$Die Association Calabash, die den Markt veranstaltet, ist ein gemeinnütziger Verein für Kinder und Familien in Sierra Leone: Gesundheitsversorgung, Kleinkredite für Frauen, kultureller Austausch mit der Schweiz. Privatleute verkaufen neben Händlern, Handwerkerinnen und Kreativen. An den Ständen gibt es nichts zu essen oder zu trinken, aber die Bäckerei Pâtisserie des Escaliers ist meistens geöffnet. Wer mit dem Auto kommt, parkt am Markttag kostenlos auf der Place du Château oder der Place du Tunnel; im Parkhaus Riponne gilt ein reduzierter Tarif.$t$),
  ($t$marche-rumine-lausanne-mardi$t$, 'de', $t$Der Marché de Rumine auf der Place de la Riponne in Lausanne ist ein Markt der Stadt ohne Lebensmittel, mit neuer und gebrauchter Ware. Seit März 2026 bringt die Dienstagsausgabe wieder Brocante-Stände auf die zentrale Riponne.$t$),
  ($t$marche-rumine-lausanne-mercredi$t$, 'de', $t$Der Marché de Rumine auf der Place de la Riponne in Lausanne ist ein Markt der Stadt ohne Lebensmittel, mit neuer und gebrauchter Ware. Seit März 2026 bringt die Mittwochsausgabe wieder Brocante-Stände auf die zentrale Riponne.$t$),
  ($t$marche-rumine-lausanne-samedi$t$, 'de', $t$Der Marché de Rumine auf der Place de la Riponne in Lausanne ist ein Markt der Stadt ohne Lebensmittel, mit neuer und gebrauchter Ware. Seit März 2026 bringt die Samstagsausgabe wieder Brocante-Stände auf die zentrale Riponne.$t$),
  ($t$marche-rumine-lausanne-vendredi$t$, 'de', $t$Der Marché de Rumine auf der Place de la Riponne in Lausanne ist ein Markt der Stadt ohne Lebensmittel, mit neuer und gebrauchter Ware. Seit März 2026 hilft die Freitagsausgabe mit, dass auf der zentralen Riponne wieder an vier Tagen pro Woche Brocante-Stände stehen.$t$),
  ($t$mercalibro-bellinzona$t$, 'de', $t$Der Mercalibro ist ein Markt für gebrauchte Bücher. Daneben gibt es Comics, Zeitschriften, Drucke, Sammel- und Postkarten, Briefmarken und anderes Gedrucktes. Es verkaufen sowohl Profis als auch Gelegenheitsverkäufer.$t$),
  ($t$mercantico-bellinzona$t$, 'de', $t$Ondemedia, der gemeinnützige Verein hinter dem Mercantico, hat seine Werkstatt und seinen Laden an der Piazza Buffi – der Markt steht also vor der eigenen Tür. Auf den Tischen: Brocante, Antiquitäten, Sammlerstücke, Vintage, Bücher und Comics, dazu das, was die Organisatoren «Grossmutters Sachen» nennen: alte Bauerngeräte, Geschirr, Stoffe und Tischwäsche, Möbel. Den Rest des Jahres rettet Ondemedia gebrauchte Bücher und verkauft sie weiter, seit 2020 getragen von Freiwilligen. Der Markt ist rollstuhlgerecht.$t$),
  ($t$mercatino-lusso-vintage-lugano$t$, 'de', $t$Gebrauchte Luxusmode und echtes Vintage: Kleidung, Accessoires, Brillen und mehr, laut Veranstalterin alles wie neu. Für den Einlass braucht jede Person ein eigenes Ticket auf ihren Namen, online über Ticket Tailor. Veranstalterin ist La Ghianda von Simona Trabucco.$t$),
  ($t$mercatino-pulci-ragazzi-locarno$t$, 'de', $t$Beim Mercatino delle pulci dei ragazzi auf der Piazza Grande in Locarno verkaufen Kinder und Jugendliche selbst: Spielzeug, Bücher, Kleidung, Sportsachen und Kleinkram. Die Erwachsenen dürfen nur helfen. Die Piazza Grande liegt fünf Minuten vom Bahnhof entfernt.$t$),
  ($t$mercatino-usato-paradiso-lugano$t$, 'de', $t$Am ersten Mittwoch des Monats, von März bis November (ausser Juli und August), findet auf der Piazza del Municipio in Paradiso, wenige Minuten von Lugano entfernt, dieser Wohltätigkeits-Flohmarkt statt. Rund 30 Stände bieten Kleidung, Accessoires, Spielsachen, Bücher und Haushaltswaren an.$t$),
  ($t$mercato-antiquariato-maghetti-lugano$t$, 'de', $t$Jeden Samstag füllen rund 40 Stände die historischen Gassen des Quartiers Maghetti in Lugano mit Antiquitäten und Gebrauchtem: Bücher, Bilderrahmen, Silberwaren, Vintage-Glas, Kleidung und Sammlerstücke. Ein Markt für die Leute aus der Gegend, das ganze Jahr über.$t$),
  ($t$midnightbazar-nachtflohmarkt-muenchen$t$, 'de', $t$Ein Nachtflohmarkt in der alten Paketposthalle, Teil der Zwischennutzung Pineapple Park. Die meisten Verkäufer räumen ihren eigenen Haushalt aus. Draussen stehen vier bis fünf Foodtrucks, drinnen gibt es Bars und ein Programm mit Musik, Comedy, Tanz oder Spieleabenden. Der günstigere Abend heisst Thrifty Friday. Kinder unter 12 zahlen nichts, Hunde an der Leine sind willkommen. An den Bars zahlst du nur mit Karte. Ab 20 Uhr ist das Tor an der Arnulfstraße zu; dann nimmst du den Eingang an der Wilhelm-Hale-Straße.$t$),
  ($t$modellbahnboerse-koeniz$t$, 'de', $t$Der Könizer Eisenbahnklub KEK veranstaltet diese Weihnachtsbörse. Neben Händlern mit Modellbahnmaterial verkauft der Klub auch Stücke im Auftrag anderer, zum Beispiel aus Nachlässen. In der Cafeteria gibt es Kuchen, Getränke und ein warmes Menü, und der Bus 10 hält bei Köniz Schloss.$t$),
  ($t$musiker-flohmarkt-zuerich-kronensaal$t$, 'de', $t$Instrumente, Equipment und Platten füllen den Kronensaal, den Saal des Hotels Kronenhof in Zürich-Affoltern. Der Name spricht von Musikern, offen ist der Markt aber für alle, zum Kaufen wie zum Verkaufen. Verkauft werden darf alles, was durch die Tür passt. Im Haus gibt es ein Café. Kleinere Autos passen in die Tiefgarage.$t$),
  ($t$nachtflohmarkt-cottbus$t$, 'de', $t$An einzelnen Samstagabenden von 15 bis 22 Uhr in zwei Messehallen, 6.000 Quadratmeter, geheizt und hell. Weit über 100 Händler; der Veranstalter nennt ihn den grössten Abendflohmarkt Brandenburgs. Neuware und Restposten sind nicht zugelassen. Eintritt 4 Euro, Kinder unter 14 frei, grosser kostenloser Parkplatz hinter der Halle.$t$),
  ($t$nachtflohmarkt-messe-erfurt$t$, 'de', $t$Etwa einmal im Monat samstags ab 16 Uhr bis in die Nacht, in den Hallen der Messe Erfurt — nach Angaben des Hauses Thüringens grösster Antik- und Trödelmarkt. Sammlerstücke und Antiquitäten. Eintritt 3 Euro, ermässigt 2. Ab dem Anger fährt die Tram 2 alle zehn Minuten.$t$),
  ($t$nachtflohmarkt-rostock$t$, 'de', $t$Zweimal im Jahr samstags von 15 bis 22 Uhr in der HanseMesse, geheizt und beleuchtet. Altes Spielzeug, Instrumente, Bücher, Bilder, Schmuck, Münzen, Porzellan, Möbel und Dinge aus DDR-Zeiten. Neuware und Restposten sind nicht zugelassen. Eintritt 3 Euro, Kinder unter 14 frei; rund 2.000 Parkplätze vor der Halle.$t$),
  ($t$nachtflohmarkt-stellwerk-bern$t$, 'de', $t$Ein Nachtflohmarkt im Stellwerk Bern: Kleidung, Schuhe, Accessoires, Haushaltswaren und mehr, am Abend, mit Livemusik und Bistro. Eintritt frei.$t$),
  ($t$nerdyartist-markthalle-basel$t$, 'de', $t$Kein Flohmarkt: NerdYartist ist ein Künstlermarkt, und alles auf den Tischen sind neue Arbeiten der Leute, die sie verkaufen – Anhänger, Prints, handgemachte Einzelstücke. Dahinter steht das Team des Nerd Yard, des Flohmarkts in der Markthalle. Der Markt lief auch schon am selben Tag wie der Nachtflohmarkt in der Halle.$t$),
  ($t$night-flohmarkt-kloten$t$, 'de', $t$Ein Flohmarkt am Abend in Kloten: Private verkaufen Haushaltswaren, Kleidung und Allerlei. Nach Einbruch der Dunkelheit geht es etwas geselliger zu als auf einem Markt am Tag. Er findet ab und zu statt, nicht nach festem Monatsplan.$t$),
  ($t$nord-flohmarkt-holstenhallen-neumuenster$t$, 'de', $t$An einzelnen Sonntagen in Halle 5 der Holstenhallen; der Termin im September findet noch draussen auf dem Freigelände statt. Plätze lassen sich vorab online buchen oder morgens ab 5.30 Uhr vor Ort nehmen; den genauen Standplatz teilt das Personal zu. Mindestens drei Meter, Strom nur an der Rückwand.$t$),
  ($t$nostalgie-flohmarkt-lyssach$t$, 'de', $t$Die Stände stehen in der Tiefgarage der Landi-Agrola und draussen auf dem Gelände. Angeboten werden Antikes, Sammlerstücke und Ware aus Haushaltsauflösungen; Fahrrad- und Elektronikhändler sind nicht zugelassen. An den Ständen gibt es nichts zu essen, Sandwiches und Kaffee findest du im Tankstellenshop der Landi. In der Tiefgarage ist Rauchen nicht erlaubt.$t$),
  ($t$nostalgie-flohmarkt-worb-bern$t$, 'de', $t$Ein Nostalgie-Flohmarkt beim Bahnhof Worb, südöstlich von Bern. Jeden zweiten Sonntag im Monat, von März bis November, bieten Händler und Private Antiquitäten, Raritäten und nostalgische Fundstücke direkt vom Auto aus an. Eine Reservierung ist nicht nötig.$t$),
  ($t$pop-up-flohmi-industrie45-zug$t$, 'de', $t$Ein Pop-up-Flohmarkt in den Räumen und auf dem Vorplatz des Jugendkulturzentrums industrie45. Am «Pimp your Clothes»-Stand kannst du mitgebrachte oder gerade gefundene Kleidung upcyceln; ausserdem sind ein Tattoo- und ein Henna-Artist da. Es gibt süsse und salzige Crêpes, Selbstgebackenes und eine Bar, Dari und Sophia Biermann spielen live.$t$),
  ($t$progr-vintage-flea-market-bern$t$, 'de', $t$In der PROGR-Turnhalle mitten in Bern findet jeden dritten Samstag im Monat von 10 bis 15 Uhr ein ausgewählter Vintage- und Secondhand-Markt statt: weniger Trödel, mehr Stil – Vintage-Stücke, Designerkleidung und Sammlerstücke.$t$),
  ($t$puces-de-nyon$t$, 'de', $t$Seit 2001 füllt der Markt die Rue de Rive und die Quais am See, vom Quai Louis Bonnard am Musée du Léman und am Hafen vorbei bis zur Grande Jetée und zur Place de Savoie. Privatleute stehen neben Brocante- und Antiquitätenhändlern. Erlaubt sind Räumungsgut, Brocante, Antiquitäten sowie Secondhand- und Vintage-Kleidung, nichts Neues und keine Fälschungen. Von April bis Oktober gehört der Parc Bourg de Rive den Kindern und Jugendlichen, unter dem Motto «Vide ta chambre» – räum dein Zimmer aus. Organisiert wird alles vom Verein des Quartier de Rive, der Leute ins Quartier und ans Seeufer bringen will.$t$),
  ($t$quartier-flohmarkt-areal-bach$t$, 'de', $t$Ein Sonntagsmarkt alle zwei Wochen, von April bis Juni, auf dem ehemaligen Bahnareal Areal Bach im Quartier St. Fiden in St. Gallen: Secondhand-Kleidung, Vintage, Bücher und Haushaltswaren von Leuten aus der Gegend, dazu ein Kaffeewagen und eine Bar.$t$),
  ($t$quartierflohmarkt-bachletten$t$, 'de', $t$Die Primarstufe Neubad hat auf ihrem Pausenhof Nord, mit Zugang von der Kaltbrunnenpromenade, einen Kinderflohmarkt veranstaltet – mit Essen von den Schulklassen sowie Spielen und Basteln für Kinder. Die Erwachsenen verkaufen in Gärten hinter den Häusern im ganzen Bachletten. Wer keinen Garten hat, verkauft im Benkenpark oder im Pfirterpark; das Essen gibt es auf dem Kiesplatz rund um die Litfasssäule im Benkenpark. Im Pfirterpärkli stellt das Amt für Umwelt und Energie ein «bring&nimm»-Zelt auf, wo Dinge kostenlos den Besitzer wechseln. Händlerinnen und Händler von ausserhalb des Quartiers stehen hinter der Pauluskirche.$t$),
  ($t$quartierflohmarkt-breite-st-alban$t$, 'de', $t$Breite und St. Alban machen ihren Flohmarkt gemeinsam – ein Spaziergang kann also durch beide Quartiere führen; welche Häuser verkaufen, zeigt der Standplan. Das «bring&nimm», wo du Brauchbares abgibst und mitnimmst, was dir gefällt, ist auf der St. Alban-Pfalz.$t$),
  ($t$quartierflohmarkt-gellert$t$, 'de', $t$Das Café Stoa stand schon mit Pizza, Getränken, Kaffee und Kuchen auf dem Standplan. Wer zu Hause keinen Platz hat, verkauft gemeinsam mit anderen an der Hardstrasse 43 beim Pförtnerhaus – parken kann man dort nicht. Das «bring&nimm» ist bei der Gellertkirche auf dem Christoph Merian-Platz.$t$),
  ($t$quartierflohmarkt-gotthelf-iselin$t$, 'de', $t$Geh nicht zum Oekolampad: Den gemeinsamen Standort dort haben die Organisatoren gestrichen, weil sich der Markt dorthin verlagert hatte, weg von den Strassen. Im Gotthelf und im Iselin sollen die Stände vor den Haustüren stehen. Wer zu Hause keinen Platz hat, verkauft auf dem Helvetiaplatz oder auf dem Westfeld, dem Areal des ehemaligen Felix Platter-Spitals. Auch das «bring&nimm» ist auf dem Helvetiaplatz.$t$),
  ($t$quartierflohmarkt-gundeli$t$, 'de', $t$Auf dem Liesbergermätteli verkaufen Kinder ihre eigenen Sachen, zusammen mit Robi Spielaktionen – ohne Anmeldung, sie kommen einfach mit einem Stand voller Kindersachen. Das mobile Xav Café macht dort Kaffee und Waffeln, Xaviers Stand Pommes. Das Pflegezentrum Falkenstein an der Falkensteinerstrasse 30 backt Crêpes, gegenüber der Haltestelle des Busses 36. Im Gundelidräff an der Ecke Solothurnerstrasse/Güterstrasse verkaufen Leute aus dem Quartier gemeinsam, drinnen und draussen; Tram 16 hält vor der Tür. Im übrigen Gundeli zeigen farbige Ballons, wo private Stände sind.$t$),
  ($t$quartierflohmarkt-hirzbrunnen$t$, 'de', $t$Für den Tag sind einige Seitenstrassen im Hirzbrunnen mit Gittern für Autos gesperrt; die Hauptstrassen und der Weg zum Claraspital bleiben offen. Die Stände stehen nur auf privatem Grund, in Gärten, Höfen und auf Vorplätzen, nicht auf der Strasse. Wer keinen Platz hat, verkauft im QTP Hirzbrunnen, Im Rheinacker 15, oder im Quartierraum Schoren – dort ist auch das «bring&nimm». Der Markt findet bei jedem Wetter statt.$t$),
  ($t$quartierflohmarkt-innerstadt$t$, 'de', $t$Auf dem Areal des OpenAir Cinema wird der Münsterplatz zum gemeinsamen Flohmarkt; die Tische leihen der Verein pro Münsterplatz und das Basler Marionetten Theater aus. Das Marionetten Theater bringt seine mobile Ainewäägeli-Bühne für kurze Aufführungen mit, dazu gibt es Essensstände. Um 16 Uhr wird auf dem Münsterplatz abgeräumt. Sonst stehen die Stände in der Innerstadt in Höfen und Gärten, und das «bring&nimm» ist an der Fasnachtsgasse.$t$),
  ($t$quartierflohmarkt-klybeck-kleinhueningen$t$, 'de', $t$Mit Kindern geht es aufs Ackermätteli: Die Spielbude Ackermätteli der Robi-Spiel-Aktionen veranstaltet einen Spielnachmittag und leiht Spielmaterial aus, und das Bistro ist geöffnet. Wer keinen eigenen Platz hat, verkauft ebenfalls dort. Das «bring&nimm» ist auf dem Wiesenplatz, die privaten Stände verteilen sich über Klybeck und Kleinhüningen.$t$),
  ($t$quartierflohmarkt-matthaeus$t$, 'de', $t$2016 begannen die Basler Quartierflohmärkte in zwei Quartieren, eines davon das Matthäus: Die Gründerin wollte einen Flohmarkt für ihr eigenes Quartier. Zum Tag gehörte auch schon ein Programm: der Florazmorge an der Florastrasse, eine Streicherschule, die im Superblock an der Oetlingerstrasse spielte, japanisches Papiertheater für Kinder auf dem Matthäusplatz, eine Pingpong-Party mit DJ an der Ecke Bläsiring/Müllheimerstrasse. Auch die Leute aus dem Quartier kochen: Der Standplan hatte eine eigene Ebene fürs Essen, mit Börek, eritreischer und äthiopischer Küche, Gözleme und Pizzen aus dem Steinofen. Das «bring&nimm» ist vor der Kirche auf dem Matthäusplatz.$t$),
  ($t$quartierflohmarkt-neubad$t$, 'de', $t$Halte Ausschau nach Kinderkleidung, Spielsachen und Lego: Viele Stände auf dem Standplan führen sie auf. Unterwegs wird gebacken und gekocht – schwedische Zimtschnecken, japanisches Kakigori-Eis, Empanadas und Salzkaramell-Popcorn standen schon auf dem Plan. Das «bring&nimm» ist auf dem Stephanus-Kirchplatz an der Furkastrasse 12. Öffentliche Toiletten gibt es auf dem Neuweilerplatz bei der Tramhaltestelle, eine rollstuhlgerechte beim Steinbühlmätteli.$t$),
  ($t$quartierflohmarkt-pratteln-gehrenacker$t$, 'de', $t$Für einen Sonntag im Jahr wird das Gebiet Gehrenacker und Fröschmatt in Pratteln zu einem weitläufigen Flohmarkt unter freiem Himmel. Die Leute aus dem Quartier verkaufen auf ihren Einfahrten, Gartenwegen und Vorplätzen, verteilt über das ganze Quartier. Das Ganze fühlt sich an wie ein riesiger Garagenflohmarkt der Nachbarschaft. Ein echter Quartieranlass und einer der eigenwilligeren Flohmärkte im Baselbiet.$t$),
  ($t$quartierflohmarkt-saeli-bruch-obergueetsch-luzern$t$, 'de', $t$Beim Quartierflohmarkt Säli, Bruch, Obergütsch verkaufen die Bewohnerinnen und Bewohner der drei Luzerner Quartiere direkt vor der Haustür, im Garten und im Innenhof. Man spaziert von Stand zu Stand; der Quartierverein veröffentlicht vorher eine Karte mit allen Verkaufsorten. An einem Sonntag im September, 10 bis 16 Uhr. Die Quartiere liegen zehn Minuten vom Bahnhof Luzern entfernt.$t$),
  ($t$quartierflohmarkt-spalen-holbein$t$, 'de', $t$Die Organisatoren nennen dieses Quartier «Am Ring». Auf dem Standplan sammeln sich die gemeinsamen Stände an zehn Orten, darunter das Spalentor, das Holbein-Plätzli, das Antilopen-Plätzli und das Schachbrett an der Ecke Nonnenweg/Socinstrasse. Das «bring&nimm» ist im Garten der Basler Mission.$t$),
  ($t$quartierflohmarkt-st-johann$t$, 'de', $t$Der Quartierflohmarkt St. Johann füllt das Quartier einen ganzen Samstag im August. Private stellen ihre Stände im ganzen Quartier auf – folge den farbigen Ballons. Über die autofreie Lothringerstrasse reicht der Markt bis ins neue Lysbüchel-Areal, mit Ständen, Spielen und Essen. Das «bring&nimm» ist im St. Johanns-Park beim Badhüsli an der Elsässerstrasse. Eine der grösseren Ausgaben der Reihe – einer von 17 Quartierflohmärkten, die der Verein Stadtprojekt in ganz Basel organisiert.$t$),
  ($t$quartierflohmarkt-wettstein$t$, 'de', $t$Für den Tag sperren Gitter die markierten Wohnstrassen für Autos; Grenzacherstrasse, Wettsteinallee, Riehenring und Peter Rot-Strasse bleiben offen. Das Wettstein war 2016 eines der beiden Quartiere, in denen die Basler Quartierflohmärkte anfingen. Wer keinen Platz hat, verkauft In der Burg beim Quartiertreffpunkt Wettstein oder auf dem Landhof-Sportplatz vor der Tribüne. Das «bring&nimm» ist neben der Kirche auf dem Theodorskirchplatz.$t$),
  ($t$quartierflohmi-neu-allschwil$t$, 'de', $t$Die Stände verteilen sich vom Morgartenring bis zur Kirche und von der Bachgraben-Promenade bis zum Langen Loh. Die Anwohnerinnen und Anwohner verkaufen auf der eigenen Einfahrt, im Vorgarten oder im Garten, und die Online-Karte zeigt jeden angemeldeten Stand. Gegründet haben den Verein Quartierflohmärkte Allschwil zwei Flohmarkt-Stammgäste, die selbst jedes Jahr dort verkaufen.$t$),
  ($t$quartierflohmi-reinach-nord$t$, 'de', $t$Beim Quartierflohmi Reinach Nord verkaufen die Bewohnerinnen und Bewohner vor der eigenen Haustür, im Garten und in der Einfahrt – die Karte auf qvrn.ch zeigt, wo. An einem Sonntag im Spätsommer, 10 bis 16 Uhr, organisiert vom Quartierverein; wer verkauft, gibt eine freiwillige Spende. Ab Basel fährt Tram 11 bis Reinach Nord.$t$),
  ($t$riesenflohmarkt-trabrennbahn-karlshorst-berlin$t$, 'de', $t$Die grosse Ausgabe des Antikflohmarkts auf der Trabrennbahn Karlshorst: drei Tage, rund 500 Aussteller mit Antiquitäten, Möbeln, Design, Kunst und viel eigenwilligem Second Hand. Wer etwas Grosses findet, kann gegen eine kleine Gebühr direkt neben den Ständen parken und es gleich einladen. In der Tribünenhalle läuft parallel die Designbörse Berlin mit Vintage-Design.$t$),
  ($t$romeo-hallenflohmarkt-muenchwilen$t$, 'de', $t$Die Dreifachhalle Waldegg füllen inzwischen jedes Mal rund 135 Ausstellerinnen und Aussteller mit Flohmarktware und Antiquitäten. Angefangen hat der Markt in einer Einfachhalle mit 75 Ständen; als es dort zu eng wurde, zog er um. Sein Name verbindet die Nachnamen der beiden Familien, die ihn betreiben. Es gibt Gegrilltes, Kuchen und Kaffee, dazu Getränke und im Dezember Glühwein; der Eingang ist stufenlos.$t$),
  ($t$rosenhof-markt-zuerich$t$, 'de', $t$In einem Innenhof der Zürcher Altstadt, zwischen Kopfsteinpflaster und Caféterrassen. Kein klassischer Trödelmarkt: Der Rosenhof setzt auf handgemachten Schmuck, Keramik, Kunsthandwerk, naive Kunst und ausgewählte Vintage-Stücke – für etwas mit Sorgfalt Gemachtes statt für ein Schnäppchen.$t$),
  ($t$saeuliaemtler-flohmarkt-affoltern$t$, 'de', $t$Es gibt genau einen Essstand: den Staffras Imbiss, den inzwischen die Swiss Fire Devils führen. Den Markt gibt es seit mehr als 35 Jahren. Bis Marktschluss bleibt der Kronenplatz frei von Autos. Parken beim Sportplatz Moos kostet jetzt Geld, wie jeder Parkplatz in Affoltern.$t$),
  ($t$slow-fashion-market-lausanne$t$, 'de', $t$Ein Markt für langsamere Mode, an einem einzigen Tag: unabhängige Designerinnen und Designer, verantwortungsvolle Labels, ausgewählte Vintage- und Secondhand-Kleidung, Schmuck und Textilhandwerk, im Casino de Montbenon. Lawen Lounge organisiert ihn, mit DJ-Set und einer Ecke für Essen und Getränke.$t$),
  ($t$strandgut-flohmarkt-neubad-luzern$t$, 'de', $t$Der Markt füllt das leere Becken des ehemaligen Hallenbads Biregg, heute das Kulturzentrum Neubad; draussen wird nichts aufgebaut. Es gibt antiquarische Bücher, Kunsthandwerk, Taschen, Schuhe und Kleidung, Technik und Werkzeug, Musik und Lampen. Erlaubt ist nur klar Gebrauchtes sowie Kunst und Handwerk, also keine Restposten und keine Massenware. Feilschen ist ausdrücklich erwünscht. Für Essen und Trinken sorgen die Poolbar und das Neubad Bistro, Hunde sind auf dem Markt nicht erlaubt. Vom Bahnhof sind es rund zehn Minuten zu Fuss, oder du nimmst den Bus 4 Richtung Hubelmatt bis Steghof; Parkplätze sind in der Nähe rar.$t$),
  ($t$strassenflohmarkt-rafz$t$, 'de', $t$Der Strassenflohmarkt Rafz findet einmal im Jahr im Dorfzentrum statt: Private Verkäufer füllen die Strassen des Ortes. Das Angebot ist klassisch: Haushaltswaren, Kleidung, Kindersachen, Bücher, Funde aus Dachboden und Keller. Für Kinder gibt es ein Karussell und Spiele, im Märtkafi selbstgebackene Kuchen, Getränke und über Mittag Flammkuchen. Rafz liegt im äussersten Norden des Kantons, nahe der deutschen Grenze – ein Geheimtipp für Flohmarktfans aus dem Unterland und dem benachbarten Schaffhausen.$t$),
  ($t$svuotacantine-ascona$t$, 'de', $t$Der Mercatino Svuotacantine Ascona ist ein Kellerräumungsmarkt auf dem Manor-Parkplatz an der Via Ferrera: Private verkaufen aus dem Kofferraum und vom Tisch, bis zu 99 Stände, nur gebrauchte Dinge aus Keller, Dachboden und Garage – keine Neuware, keine Lebensmittel. Dreimal im Jahr an einem Sonntag, 9 bis 17 Uhr; bei Regen eine Woche später. Der Verein I Mercantini veranstaltet ähnliche Märkte in Biasca, Muralto, Giubiasco und Sant'Antonino.$t$),
  ($t$svuotacantine-biasca$t$, 'de', $t$Der Mercatino Svuotacantine Biasca ist der Kellerräumungsmarkt des Vereins I Mercantini auf dem zentralen Manor-Parkplatz in Biasca: Rund 65 Private verkaufen aus dem Kofferraum, nur Gebrauchtes aus Keller, Dachboden und Garage. Zweimal im Jahr an einem Sonntag; bei Regen eine Woche später. Bushaltestellen und Parkplätze für Besucher liegen wenige Meter entfernt.$t$),
  ($t$svuotacantine-muralto$t$, 'de', $t$Von allen Kellerräumungsmärkten, die I Mercantini im Tessin veranstalten, ist dieser auf dem Burbaglio der einzige am Abend – jeder Platz hat seine eigene Beleuchtung. Verkauft werden darf nur klar Gebrauchtes aus dem eigenen Keller oder vom eigenen Dachboden. Hinter dem Verein stehen Freiwillige, die die Svuotacantine 2018 auf dem Manor-Parkplatz in Ascona gestartet haben und damit Menschen in Not unterstützen.$t$),
  ($t$swiss-vintage-and-design-market-granges-paccot$t$, 'de', $t$Ein Markt für Vintage und Design im Forum Fribourg. Veranstalter ist Dakota Events, ein Familienbetrieb aus Poliez-Pittet, der am selben Ort auch eine Brocante und mehrere Sammlerbörsen veranstaltet.$t$),
  ($t$troedelmarkt-barmen-rathaus-wuppertal$t$, 'de', $t$An einem Sonntag im Monat von 11 bis 18 Uhr direkt am Barmer Rathaus, mitten in der Stadt. Gebrauchtes und Neuware nebeneinander, dazu Essens- und Getränkestände. Eintritt frei; Parkhäuser gibt es in der Nähe, und rund ein Dutzend Buslinien halten am Rathaus.$t$),
  ($t$troedelmarkt-globus-saarbruecken-guedingen$t$, 'de', $t$Etwa einmal im Monat, meist sonntags von 11 bis 18 Uhr, mit überdachten Ständen. Kleidung, Deko, Bücher, Raritäten und Vintage-Funde. Geparkt wird im Parkhaus, Essen und Trinken gibt es vor Ort. Bus 126 hält vor der Tür, und die A6 und die A620 sind nicht weit.$t$),
  ($t$troedelmarkt-hansamarkt-berlin$t$, 'de', $t$Trödelmarkt und Wochenmarkt in einem, in Weißensee. Zwischen den Ständen mit Gebrauchtem gibt es frisches Obst und Gemüse und frisch geräucherten Fisch – Forelle, Aal, Makrele. Die Feldküche hat Currywurst, Hausmannskost und Softeis, falls das Stöbern länger dauert.$t$),
  ($t$troedelmarkt-ikea-koeln-butzweilerhof$t$, 'de', $t$Etwa einmal im Monat von 11 bis 18 Uhr beim IKEA am Butzweilerhof, direkt am Autobahnkreuz Köln-Nord. Trödel und Neuware in grosser Auswahl, dazu viele Essensstände. Erreichbar mit der Linie 5 und dem Bus 139; der Eintritt ist frei.$t$),
  ($t$troedelmarkt-ikea-koeln-godorf$t$, 'de', $t$Meist am vierten Sonntag im Monat von 11 bis 18 Uhr beim IKEA zwischen Rodenkirchen und Godorf. Vor Ort gibt es Essensstände, geparkt wird bei IKEA, METRO oder OBI. Die Strassenbahnlinie 16 fährt bis Godorf Bahnhof; der Eintritt ist frei.$t$),
  ($t$troedelmarkt-ruhr-park-bochum$t$, 'de', $t$An einem Sonntag im Monat von 11 bis 17 Uhr auf dem Parkplatz P1 am Westfield RuhrPark. Gebrauchte Elektrogeräte, Sammlerstücke, Kleidung und Neuware, von privaten und gewerblichen Verkäufern; der Veranstalter zählt über zehntausend Besucher im Monat. Es gibt eine ganze Reihe Essensstände. Fünf Minuten von der A40.$t$),
  ($t$troedelmarkt-universitaet-dortmund$t$, 'de', $t$Jeden Samstag von 7 bis 14 Uhr auf den Parkplätzen der TU Dortmund, ausser an Feiertagen. Private Verkäufer mit Gebrauchtem neben Händlern mit Neuware; Markenfälschungen sind streng verboten. Der Veranstalter nennt ihn einen der bekanntesten und ältesten Märkte der Stadt. S-Bahn Dortmund Universität, Bus 447 und 462.$t$),
  ($t$vide-dressing-flon-lausanne$t$, 'de', $t$Secondhand-Kleidung, Accessoires und Gegenstände: ein Vide-Dressing und ein Vide-Grenier in einem, mitten im Flon-Quartier. Die Association des Amis du Chibre veranstaltet ihn zusammen mit dem Quartier du Flon – Chibre ist der Westschweizer Name für das Kartenspiel Jass.$t$),
  ($t$vide-grenier-bern-altstadt$t$, 'de', $t$Bewohnerinnen, Bewohner und Geschäfte der unteren Altstadt räumen Keller und Dachboden und breiten alles in der Kram- und Gerechtigkeitsgasse aus. Die Tische stehen unter den Lauben oder vor den Läden, nie auf der Strasse. Kinder, die in diesen Gassen wohnen, verkaufen ihre Sachen ohne Standgebühr. Die Idee stammt von zwei Mitgliedern des Kramgass-Leists, und den Markt gibt es seit mehr als zwanzig Jahren; heute steht er unter der Schirmherrschaft der Vereinigten Altstadtleiste.$t$),
  ($t$vide-grenier-brocante-les-brenets$t$, 'de', $t$Die Association pour les Enfants des Brenets veranstaltet diesen Markt, einen Vide-grenier mit Brocante. An der Bar gibt es Raclette, dazu Sandwiches und Gebäck.$t$),
  ($t$vide-grenier-echichens$t$, 'de', $t$Die Association Enfants bestückt ihre Stände mit Sachen, die ihr geschenkt wurden – das ganze Jahr über gesammelt und sortiert in ihren Räumen unter der Salle polyvalente. Auf den Tischen: Haushalt und Deko, Krimskrams, Bücher, Vinyl, Spiele und Spielsachen, Kleidung für Frauen, Männer, Jugendliche und Kinder, alles zu kleinen Preisen. Das Geld geht an Kinder, heute vor allem in der Nähe: Über die Sozialdienste bezahlt der Verein etwa Musikstunden, Winterkleidung, Hausaufgabenbetreuung und Ferienlager. Gegründet wurde er 1983, nachdem Freiwillige Hilfskonvois zu einem Waisenhaus bei Warschau gefahren hatten. Es gibt einen Imbiss mit Essen, und Parken ist kostenlos.$t$),
  ($t$vide-grenier-ecobroc-saxon$t$, 'de', $t$Der Markt findet bei EcoBroc statt, einem Secondhand-Laden in Saxon, der Hausrat abholt, sortiert, Wohnungen räumt und alles weiterverkauft. Mitbringen kann jede und jeder, was nicht mehr gebraucht wird: Deko, Geschirr, kleine Möbel, Spielsachen, Kleidung, Bücher, alte Gegenstände und manch seltsamen Fund. In der Verpflegungsecke gibt es Kaffee und Croissants, Sandwiches, Wein und Mineralwasser. Der Laden ist an Markttagen ebenfalls geöffnet, du kannst also auch dort stöbern.$t$),
  ($t$vide-grenier-familles-renens$t$, 'de', $t$Der Vide-grenier spécial familles in Renens ist ein Flohmarkt für Kinderkleidung, Spielzeug, Kinderbücher und Babysachen in der Salle de spectacles an der Rue de Lausanne 37, organisiert von Bulle d'air, dem Familienangebot der reformierten Kirche. Vom Bahnhof Renens sind es zehn Minuten zu Fuss.$t$),
  ($t$vide-grenier-lutry$t$, 'de', $t$Verkaufen dürfen nur Leute, die in Lutry wohnen, ein Platz pro Familie; professionelle Händler sind ausgeschlossen. Organisiert wird der Markt von der Société de Développement de Lutry. Sie wurde Anfang des 20. Jahrhunderts gegründet, setzt sich für das kulturelle, soziale und wirtschaftliche Leben im Ort ein und veranstaltet auch den Weihnachtsmarkt.$t$),
  ($t$vide-grenier-onex$t$, 'de', $t$Der Vide-grenier d'Onex ist der Quartierflohmarkt der Genfer Vorortsgemeinde: rund 80 Stände auf der Place du 150ème, mitten in Onex-Cité, organisiert vom Quartierverein AHOC. Ab Genf fährt Tram 14 bis Onex-Cité, der Platz liegt direkt an der Haltestelle.$t$),
  ($t$vide-grenier-place-de-milan-lausanne$t$, 'de', $t$Der Vide-Grenier de la Place de Milan findet im Parc de Milan statt, mitten im Lausanner Quartier Sous-Gare. Private bieten Kleidung, Spielzeug, Nippes und allerlei Haushaltsgegenstände an. Ein geselliger, leicht zugänglicher Flohmarkt in Lausanne, organisiert von der Association Sous-Gare et Cour.$t$),
  ($t$vide-grenier-sallaz-lausanne$t$, 'de', $t$L'Escale des Voisins, ein Nachbarschaftsverein in La Sallaz, veranstaltet diesen Markt, damit die Leute im Quartier zusammenkommen. Kinder unter zwölf bekommen ihren Platz gratis, ein paar der Verkäufer sind also klein. Die Ausgabe im September war schon Teil des autofreien Tags der Stadt Lausanne, mit kostenlosen Spiel- und Bastelateliers, Kinderschminken, einem Café littéraire, Musik und Snacks.$t$),
  ($t$vide-grenier-villars-tiercelin$t$, 'de', $t$In der Grande salle von Villars-Tiercelin (Jorat-Menthue) findet ein Vide-grenier statt.$t$),
  ($t$vrd-flohmarkt-riehen$t$, 'de', $t$Die Vereinigung Riehener Dorfgeschäfte, 1979 gegründet, um den Dorfkern zu beleben, veranstaltet diesen Markt auf dem Dorfplatz und im Webergässchen. Mehr als 20 Ausstellerinnen und Aussteller kommen, und die Regeln lassen nur gebrauchte Ware zu. Rechne nicht mit einem Snack am Stand: Essen und Getränke stehen auf der Verbotsliste, zusammen mit Waffen und gefälschten Markenartikeln.$t$),
  ($t$wbz-flohmarkt-reinach$t$, 'de', $t$Der WBZ-Flohmarkt in Reinach dauert vier Tage, jedes Jahr Ende Oktober, im Wohn- und Bürozentrum für Körperbehinderte (WBZ) an der Aumattstrasse 71: Kleidung, Haushaltswaren, Geschirr, Bücher, Schmuck, Korbwaren, Elektronik und Antiquitäten, nach Themen sortiert. Der Erlös kommt direkt Menschen mit Behinderung zugute und finanziert ihre Arbeitsplätze mit.$t$),
  ($t$xxl-flohmarkt-messe-kassel$t$, 'de', $t$Mehrere Wochenenden im Jahr in den Hallen der Messe Kassel und auf dem Freigelände davor, samstags und sonntags. Gebrauchtes und Antiquitäten, dazu etwas Neuware. Der kleinste Stand misst zwei Meter; draussen kann das Auto am Stand bleiben.$t$),
  ($t$flohmarkt-alte-holzbruecke-olten$t$, 'en', $t$The flea market on the old wooden bridge is Olten's landmark flea market: stands on the covered wooden bridge over the Aare in the middle of town, from March to October on the last Saturday of the month, 7.30 am to 5 pm. The bridge is three minutes from Olten station.$t$),
  ($t$flohmarkt-alte-holzbruecke-olten$t$, 'fr', $t$Le marché aux puces du vieux pont de bois est l'emblème d'Olten : des stands sur le pont couvert qui enjambe l'Aar, en plein centre, de mars à octobre le dernier samedi du mois, de 7 h 30 à 17 h. Le pont est à trois minutes de la gare d'Olten.$t$),
  ($t$flohmarkt-alte-holzbruecke-olten$t$, 'it', $t$Il mercatino delle pulci sul vecchio ponte di legno è il mercatino simbolo di Olten: bancarelle sul ponte coperto che attraversa l'Aar, in pieno centro, da marzo a ottobre l'ultimo sabato del mese, dalle 7.30 alle 17. Il ponte è a tre minuti dalla stazione di Olten.$t$),
  ($t$flohmarkt-dorfplatz-horgen$t$, 'en', $t$The flea market on Horgen's Dorfplatz takes place five times a year in and around the Dorfplatz tent, Saturdays 9 am to 4 pm, organised by the Dorfchärn association. Art, secondhand, toys and clothes. Coffee, cake and grilled sausages on site. The car park under the square has a lift straight up; five minutes from Horgen station.$t$),
  ($t$flohmarkt-dorfplatz-horgen$t$, 'fr', $t$Le Flohmi de la Dorfplatz de Horgen a lieu cinq fois par an dans et autour de la tente de la place, le samedi de 9 h à 16 h, organisé par l'association Dorfchärn. Art, seconde main, jouets et habits. Café, gâteaux et saucisses grillées sur place. Le parking sous la place a un ascenseur qui monte directement ; cinq minutes depuis la gare de Horgen.$t$),
  ($t$flohmarkt-dorfplatz-horgen$t$, 'it', $t$Il Flohmi sulla Dorfplatz di Horgen si tiene cinque volte l'anno dentro e attorno al tendone della piazza, il sabato dalle 9 alle 16, organizzato dall'associazione Dorfchärn. Arte, seconda mano, giocattoli e vestiti. Caffè, torte e salsicce alla griglia sul posto. Il parcheggio sotto la piazza ha un ascensore diretto; cinque minuti dalla stazione di Horgen.$t$),
  ($t$herbst-flohmarkt-richterswil$t$, 'en', $t$The Richterswil autumn flea market is the municipality's flea market on the Wisshusplatz in the village centre. No food or drink is sold at the stands. Five minutes on foot from Richterswil station; day parking cards are available online.$t$),
  ($t$herbst-flohmarkt-richterswil$t$, 'fr', $t$Le marché aux puces d'automne de Richterswil est celui de la commune, sur la Wisshusplatz au centre du village. Pas de nourriture ni de boissons aux stands. Cinq minutes à pied depuis la gare de Richterswil ; cartes de parking journalières en ligne.$t$),
  ($t$herbst-flohmarkt-richterswil$t$, 'it', $t$Il mercatino autunnale di Richterswil è quello del comune, sulla Wisshusplatz nel centro del paese. Alle bancarelle non si vendono cibo e bevande. Cinque minuti a piedi dalla stazione di Richterswil; tessere giornaliere per il parcheggio online.$t$),
  ($t$floh-raritaetenmarkt-europaplatz-bern$t$, 'en', $t$A flea and rarities market on Europaplatz in Bern. Private sellers and dealers offer antiques, rarities and all kinds of second-hand goods.$t$),
  ($t$floh-raritaetenmarkt-europaplatz-bern$t$, 'fr', $t$Marché aux puces et aux raretés sur l’Europaplatz à Berne. Vendeurs privés et marchands proposent antiquités, raretés et articles de seconde main en tout genre.$t$),
